(2, '', 'armorum_banner1.jpg', NULL, '', '', '', '<h2 style=\"text-align: right;\">&nbsp;</h2>\r\n<h2 style=\"text-align: center;\"><strong><span style=\"font-size: 55px;\">&nbsp;<span style=\"color: #ffffff;\">ARMORUM FINANCIAL PARTNER</span></span></strong></h2>\r\n<h2 style=\"text-align: center;\"><span style=\"font-size: 38px; color: #00ccff;\"><strong>S</strong><strong>omos parte de su equipo</strong></span></h2>', '', 0, 0, 0, 0, 1, 1, 0, 1, NULL),
(3, '', '', NULL, 'fondo_4-min22.jpg', '', '', '<h2 style=\"text-align: center;\"><span style=\"color: #ffffff; font-size: 65px;\"><strong>Nuestros servicios</strong></span></h2>', '', 0, 0, 0, 0, 1, 2, 0, 1, 0),
(4, '', '', NULL, 'fondo_circulos_blanco-min2.jpg', '', '', '<h2 class=\"bloqueDe1AexperienciaBlanco\" style=\"text-align: center;\" align=\"center\"><span style=\"font-size: 65px; color: #34495e;\"><strong>Nuestros sectores</strong>&nbsp;</span></h2>\r\n<div class=\"bloqueDe1Aexperiencia\">&nbsp;</div>', '', 0, 0, 0, 0, 1, 2, 0, 1, 1486),
(5, 'Introduccion', '', NULL, '', '', '', '<ul>\r\n<li><span style=\"font-size: 22px; color: #000000;\">Tiempo eficiente</span></li>\r\n<li><span style=\"font-size: 22px; color: #000000;\">Plazos seg&uacute;n el flujo de caja de nuestros clientes</span></li>\r\n<li><span style=\"font-size: 22px; color: #000000;\">Amortizaciones ajustadas a la capacidad de pago de nuestros clientes</span></li>\r\n<li><span style=\"font-size: 22px; color: #000000;\">Tasas competitivas</span></li>\r\n<li><span style=\"font-size: 22px; color: #000000;\">Brindamos diferentes alternativas de financiaci&oacute;n convencionales y no convencionales</span></li>\r\n<li><span style=\"font-size: 22px; color: #000000;\">Liberamos carga operativa de tramites antes entidades fondeadoras</span></li>\r\n<li><span style=\"font-size: 22px; color: #000000;\">Optimizaci&oacute;n de caja por medio de desinversi&oacute;n en activos fijos</span></li>\r\n<li><span style=\"font-size: 22px; color: #000000;\">Mejoramiento de indicadores financieros</span></li>\r\n<li><span style=\"font-size: 22px; color: #000000;\">Consecuci&oacute;n de inversionistas idoneos para desarrollos inmobiliarios</span></li>\r\n</ul>', '', NULL, NULL, 0, 0, 1, 4, 0, 1, NULL),
