(11, '', 'foto_banner_2_fin.jpg', '', '', '', '', '<h2 style=\"text-align: left;\">&nbsp;</h2>\r\n<h2 style=\"text-align: left;\">&nbsp;</h2>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<h2 style=\"text-align: left;\"><span style=\"font-size: 60px;\"><span style=\"color: #3498db;\"><strong><span style=\"color: #3498db;\">Apotecarium</span>&nbsp;</strong></span></span></h2>\r\n<h2 style=\"text-align: left;\"><span style=\"font-size: 60px;\"><span style=\"color: #3498db;\"><strong>al servicio&nbsp;</strong></span><span style=\"color: #3498db;\"><strong>de </strong></span></span></h2>\r\n<h2 style=\"text-align: left;\"><span style=\"font-size: 60px;\"><span style=\"color: #3498db;\"><strong>su salud&nbsp;</strong></span></span></h2>\r\n<h2 style=\"text-align: left;\">&nbsp;</h2>\r\n<h2 style=\"text-align: left;\"><strong><span style=\"font-size: 40px; color: #217bb8;\">Laboratorio farmac&eacute;utico </span></strong></h2>\r\n<h2 style=\"text-align: left;\"><span style=\"font-size: 24px; color: #217bb8;\"><strong><span style=\"font-size: 40px;\">con 16 a&ntilde;os de trayectoria</span>&nbsp;</strong></span></h2>\r\n<p><span style=\"color: #3498db;\">&nbsp;</span></p>\r\n<h2 style=\"text-align: left;\">&nbsp;</h2>\r\n<p><strong>&nbsp;</strong></p>\r\n<p><strong>&nbsp;</strong></p>\r\n<p><strong>&nbsp;</strong></p>', '', 0, 0, 0, 0, 2, 1, 0, 1, NULL),
(12, '', 'foto_banner_1_fin.jpg', '', '', '', '', '<h2 style=\"text-align: left;\">&nbsp;</h2>\r\n<h2 style=\"text-align: left;\">&nbsp;</h2>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<h2 style=\"text-align: left;\"><span style=\"font-size: 60px;\"><strong><span style=\"color: #3498db;\">Apotecarium</span></strong></span></h2>\r\n<h2 style=\"text-align: left;\"><span style=\"font-size: 60px;\"><strong><span style=\"color: #3498db;\">medicamentos </span></strong></span></h2>\r\n<h2 style=\"text-align: left;\"><span style=\"font-size: 60px;\"><strong><span style=\"color: #3498db;\">de confianza</span></strong></span></h2>\r\n<h2 style=\"text-align: left;\">&nbsp;</h2>\r\n<h2 style=\"text-align: left;\"><span style=\"font-size: 40px; color: #217bb8;\"><strong>Contamos con m&aacute;s de </strong></span></h2>\r\n<h2 style=\"text-align: left;\"><span style=\"font-size: 40px; color: #217bb8;\"><strong>285 farmacias en el pa&iacute;s</strong></span></h2>\r\n<h2 style=\"text-align: left;\">&nbsp;</h2>\r\n<h2 style=\"text-align: left;\">&nbsp;</h2>\r\n<h2 style=\"text-align: left;\">&nbsp;</h2>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>', '', 0, 0, 0, 0, 2, 1, 0, 1, NULL),
