(137, '', 'armorum_banner2.jpg', NULL, '', '', '', '<h2 style=\"text-align: left;\">&nbsp;</h2>\r\n<h2 style=\"text-align: left;\">&nbsp;</h2>\r\n<h2 style=\"text-align: center;\"><span style=\"font-size: 55px; color: #ffffff;\"><strong>SERVICIOS FINANCIEROS&nbsp;</strong><strong>A LA MEDIDA</strong></span></h2>\r\n<h2 style=\"text-align: center;\"><span style=\"font-size: 38px; color: #00ccff;\"><strong>Alternativas de financiaci&oacute;n convencionales </strong></span><span style=\"font-size: 30px;\"><strong><span style=\"color: #243b53;\"><span style=\"font-size: 28px;\"><span style=\"color: #00ccff; font-size: 38px;\">y no convencionales en pesos y d&oacute;lares</span>&nbsp;</span> &nbsp;</span> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</strong></span></h2>', '', 0, 0, 0, 0, 1, 1, 0, 1, 137),
