(200, '', '', NULL, 'gris_2.jpg', '#cccccc', '', '<h2 style=\"text-align: center;\"><strong><span style=\"font-size: 60px; color: #808080;\"><span style=\"font-size: 50px; color: #000000;\">BENEFICIOS</span>&nbsp;</span></strong></h2>', '', 0, 0, 0, 0, 3, 2, 0, 1, 95),
(201, '', '', NULL, '', '', '', '<ul class=\"ul1\">\r\n<ul class=\"ul1\">\r\n<ul class=\"ul1\">\r\n<li class=\"li1\"><span style=\"font-size: 16px; color: #808080;\"><strong><span class=\"s2\">Establece un modelo de innovaci&oacute;n permanente.</span></strong></span></li>\r\n</ul>\r\n</ul>\r\n</ul>\r\n<ul class=\"ul1\">\r\n<ul class=\"ul1\">\r\n<ul class=\"ul1\">\r\n<li class=\"li1\"><span style=\"font-size: 16px; color: #808080;\"><strong><span class=\"s2\">Integra la expectativa y experiencia de: los<span class=\"Apple-converted-space\">&nbsp;&nbsp;</span>directivos, el personal en la fase 1, y (el cliente, los proveedores y la competencia en la fase 2/ No incluida )</span></strong></span></li>\r\n</ul>\r\n</ul>\r\n</ul>\r\n<ul class=\"ul1\">\r\n<ul class=\"ul1\">\r\n<ul class=\"ul1\">\r\n<li class=\"li1\"><span style=\"font-size: 16px; color: #808080;\"><strong><span class=\"s2\">Alinea la estrategia de la organizaci&oacute;n hacia el incremento de ventas.</span></strong></span></li>\r\n</ul>\r\n</ul>\r\n</ul>', '', 0, 0, 200, 6, 3, 3, 0, 1, 201);
