(421, '', '', NULL, 'foto_clinica-min.jpg', '#ffffff', '', '<div class=\"text-center\" style=\"text-align: center;\">\r\n<p style=\"text-align: center;\"><span style=\"color: #5d2c85; font-size: 38px;\"><strong>DRAPIDO, TU CITA M&Eacute;DICA PARA HOY O MA&Ntilde;ANA</strong></span></p>\r\n<h3>&nbsp;</h3>\r\n</div>', '', 0, 0, 0, 0, 8, 2, 0, 1, NULL),
(424, '', 'portada_20.jpg', NULL, '', '', '', '<p style=\"text-align: left;\">&nbsp;</p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: 40px;\"><span style=\"color: #ffffff;\"><strong style=\"color: #ffffff; font-size: 40px;\">La aplicaci&oacute;n </strong><span style=\"color: #ffffff;\"><strong>m&oacute;vil</strong></span><strong style=\"color: #ffffff; font-size: 40px;\">&nbsp;</strong></span><span style=\"color: #ffffff;\"><strong>que&nbsp;</strong></span><span style=\"color: #ffffff;\"><strong>te </strong></span><span style=\"color: #ffffff;\"><strong>permite </strong></span></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: 40px;\"><span style=\"color: #ffffff;\"><strong>reservar&nbsp;</strong></span><span style=\"color: #ffffff;\"><strong>tu </strong></span><span style=\"color: #ffffff;\"><strong>cita hoy o ma&ntilde;ana</strong></span></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: 20px;\"><span style=\"color: #ffffff;\">Desde cualquier lugar en el que te encuentres</span></span></p>', '', 0, 0, 0, 0, 8, 1, 0, 1, 424),
(425, '', '3_portada.jpg', NULL, '', '', '', '<p style=\"text-align: left;\"><span style=\"font-size: 40px;\"><span style=\"color: #ffffff;\"><strong style=\"color: #ffffff; font-size: 40px;\">La aplicaci&oacute;n&nbsp;que conecta&nbsp;</strong></span></span><span style=\"font-size: 40px;\"><span style=\"color: #ffffff;\"><strong style=\"color: #ffffff; font-size: 40px;\">a sus</strong></span></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: 40px;\"><span style=\"color: #ffffff;\"><strong style=\"color: #ffffff; font-size: 40px;\"> pacientes con sus doctores</strong></span></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: 20px;\"><span style=\"color: #ffffff;\">Encuentra los mejores especialistas de cada &aacute;rea&nbsp;</span></span></p>', '', 0, 0, 0, 0, 8, 1, 0, 1, 425),
(426, '', '4_portada.jpg', NULL, '', '', '', '<p style=\"text-align: left;\"><span style=\"font-size: 40px;\"><span style=\"color: #ffffff;\"><strong style=\"color: #ffffff; font-size: 40px;\">Una aplicaci&oacute;n disponible las </strong></span></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: 40px;\"><span style=\"color: #ffffff;\"><strong style=\"color: #ffffff; font-size: 40px;\">24 horas del d&iacute;a</strong></span></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: 20px;\"><span style=\"color: #ffffff;\">Asegurando la atenci&oacute;n el momento que necesite</span></span></p>', '', 0, 0, 0, 0, 8, 1, 0, 1, 426),
