(767, 'Texto Contacto', '', NULL, 'fondo35.jpg', '', '', '<p style=\"text-align: center;\"><span style=\"color: #ffffff; font-size: 30px;\"><strong>LOREM IPSUM</strong></span></p><p style=\"text-align: center;\"><span style=\"color: #ffffff; font-size: 22px;\">Lorem Ipsum&nbsp;is simply dummy text of the printing and typesetting industry. Lorem Ipsum has been the industrys standard dummy text ever since the 1500s, when an unknown printer took a galley of type and scrambled it to make a type specimen book.</span></p>', '', 0, 0, 0, 0, 19, 2, 4, 0, NULL),
(769, '', '', NULL, '', '', '', '<p style=\"text-align: center;\"><span style=\"font-size: 30px; color: #e0b404;\"><strong>FLOW</strong></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: 40px;\"><strong><span style=\"color: #8db557;\">Su billetera, en su tel&eacute;fono m&oacute;vil</span></strong></span></p>', '', 0, 0, 0, 0, 10, 2, 0, 1, 769),
(770, '', 'celular.jpg', NULL, '', '', '', '', '', 0, 0, 769, 6, 10, 3, 0, 1, 770),
(771, '', 'logo_flow1.jpg', NULL, '', '', '', '<p style=\"text-align: justify;\"><span style=\"font-size: 18px; color: #000000;\"><span style=\"font-size: 40px;\"><strong><span style=\"color: #8db557;\">Flow</span></strong></span><span style=\"font-size: 24px;\">, es una billetera&nbsp;m&oacute;vil dise&ntilde;ada para facilitar el estilo de vida de las personas. Por medio de nuestra App, las personas podr&aacute;n transferir dinero y realizar cualquier tipo de compras y pagos.</span></span></p>\r\n<p style=\"text-align: justify;\"><span style=\"font-size: 24px; color: #000000;\">Todos estos movimientos o transacciones se realizar&aacute;n en tiempo real, es decir su dinero viaja por la red de forma inmediata.</span></p>', '', 0, 0, 769, 6, 10, 3, 0, 1, 771),
(774, '', '', NULL, '', '#8db557', '', '<p style=\"text-align: center;\"><span style=\"font-size: 40px;\"><strong><span style=\"color: #ffffff;\">&iquest;C&Oacute;MO FUNCIONA?</span></strong></span></p>', '', 0, 0, 0, 0, 10, 2, 0, 1, 774),
(775, '', 'billetera_icono.png', NULL, '', '', '', '<p style=\"text-align: center;\"><span style=\"color: #000000;\">&nbsp;</span></p>\r\n<p style=\"text-align: center;\"><span style=\"color: #000000;\"><span style=\"font-size: 20px;\">&nbsp;<span style=\"color: #ffffff;\">Es u</span></span><span style=\"font-size: 20px; color: #ffffff;\">na billetera m&oacute;vil que se puede usar desde cualquier dispositivo, m&oacute;vil Android, IOs y an&aacute;logos.</span></span></p>', '', 0, 0, 774, 3, 10, 3, 0, 1, 775),
(776, '', 'celular_icono.png', NULL, '', '', '', '<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: 20px; color: #ffffff;\">&nbsp;La billetera m&oacute;vil funciona s&oacute;lo con su n&uacute;mero de celular, sin necesidad de tener una cuenta bancaria. No m&aacute;s bancos, ni tarjetas para los usuarios.</span></p>', '', 0, 0, 774, 3, 10, 3, 0, 1, 776),
(777, '', 'ahorro_icono.png', NULL, '', '', '', '<p style=\"text-align: center;\"><span style=\"color: #000000;\">&nbsp;</span></p>\r\n<p style=\"text-align: center;\"><span style=\"color: #ffffff;\"><span style=\"font-size: 20px;\">Reduce tiempos de movilidad y&nbsp;ahorro en&nbsp; sus transacciones. </span><span style=\"font-size: 20px;\">&nbsp;Realizar transferencias a otros usuarios a un m&iacute;nimo costo.</span></span></p>', '', 0, 0, 774, 3, 10, 3, 0, 1, 777),
(778, '', 'tarjeta_icono.png', NULL, '', '', '', '<p style=\"text-align: center;\"><span style=\"color: #000000;\">&nbsp;</span>&nbsp;</p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: 20px; color: #ffffff;\">No m&aacute;</span><span style=\"font-size: 20px; color: #ffffff;\">s costos elevados por transacciones, ni m&aacute;s uso de dat&aacute;fonos para los comerciantes.</span></p>', '', 0, 0, 774, 3, 10, 3, 0, 1, 778),
(780, '', 'togroow_soluciones-01.jpg', '', '', '', '', '<h2 style=\"text-align: right;\"><span style=\"font-size: 16px; color: #ffffff;\">&nbsp; &nbsp; &nbsp;</span></h2>\r\n<h3 style=\"text-align: left;\">&nbsp;</h3>', '', 0, 0, 0, 0, 12, 1, 0, 1, 780),
(783, '', '', NULL, '', '', '', '', '', 0, 0, 0, 0, 10, 2, 0, 1, 783),
(784, '', 'togroow_soluciones-02.jpg', '', '', '', '', '<h2 style=\"text-align: left;\">&nbsp;</h2>\r\n<h3 style=\"text-align: left;\">&nbsp;</h3>', '', 0, 0, 0, 0, 12, 1, 0, 1, 784),
(786, '', '', NULL, '', '', '<p style=\"text-align: center;\"><span style=\"font-size: 18px; color: #fe0000;\">Creamos la vitrina digital de tu empresa. Logra estar presente para tus clientes en el momento indicado</span></p>', '', '', 90, 0, 785, 6, 12, 4, 0, 1, 786),
(787, '', '', NULL, '', '', '<p style=\"text-align: center;\"><span style=\"color: #fe0000; font-size: 18px;\">Atrae a nuevos prospectos y aumenta la conversi&oacute;n de tus visitantes</span></p>', '', '', 91, 0, 785, 6, 12, 4, 0, 1, 787),
(789, '', 'celular_flow.png', NULL, '', '', '', '', '', 0, 0, 783, 6, 10, 3, 0, 1, 789);
INSERT INTO `contenido_page` (`contenido_page_id`, `contenido_page_titulo`, `contenido_page_imagen`, `contenido_page_ruta_imagen`, `contenido_page_fondo_image`, `contenido_page_fondo_color`, `contenido_page_introdiccion`, `contenido_page_descripcion`, `contenido_page_enlace`, `contenido_page_producto`, `contenido_page_diseno`, `contenido_page_padre`, `contenido_page_columna`, `contenido_page_pageid`, `contenido_page_tipo`, `contenido_page_boton`, `contenido_page_tipocontenido`, `orden`) VALUES
(790, '', '', NULL, '', '', '', '<p style=\"text-align: center;\"><span style=\"font-size: 40px;\"><strong><span style=\"color: #8db557;\">NUESTROS&nbsp;BENEFICIOS</span></strong></span></p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<ul>\r\n<li><span style=\"font-size: 20px;\">Soluci&oacute;n para el problema de la fabricaci&oacute;n de los billetes, mediante nuestra app&nbsp;<span style=\"font-size: 30px; color: #8db557;\"><strong>Flow</strong></span> se desincentiva el uso del papel moneda y a su vez la reducci&oacute;n del uso de divisas extranjeras como el d&oacute;lar para su adquisici&oacute;n.</span></li>\r\n</ul>\r\n<ul>\r\n<li><span style=\"font-size: 20px;\">Transferencia de dinero entre usuarios o a corresponsales en tiempo real.</span></li>\r\n<li><span style=\"font-size: 20px;\">No requiere cuenta bancaria.</span></li>\r\n<li><span style=\"font-size: 20px;\">No m&aacute;s bancos, ni tarjetas y cobros usureros por el uso de estos servicios.</span></li>\r\n<li><span style=\"font-size: 20px;\">No se requiere puntos de venta (dat&aacute;fonos) para los comerciantes.</span></li>\r\n<li><span style=\"font-size: 20px;\">Reducci&oacute;n de tiempos de movilidad y costos para personas que viven lejos de las ciudades, mejorando la calidad de vida.</span></li>\r\n</ul>', '', 0, 0, 783, 6, 10, 3, 0, 1, 790),
(796, '', 'togroow_soluciones-11.jpg', '', '', '', '', '<h2 style=\"text-align: left;\">&nbsp;</h2>', '', 0, 0, 0, 0, 12, 1, 0, 1, 796),
(803, '', 'togroow_d_images09.jpg', '', '', '', '', '', '', 0, 0, 0, 0, 12, 2, 3, 1, 803),
(804, '', '', '', '', '', '', '<h3 style=\"text-align: center;\"><strong><span style=\"font-size: 28px;\"><span style=\"color: #808080;\">NUESTROS BENEFICIOS</span></span></strong></h3>', '', 0, 0, 575, 12, 8, 3, 0, 2, 587),
(807, '', '', NULL, '', '', '', '<h2 style=\"text-align: center;\"><span style=\"color: #ffffff;\"><strong>SIN REALIZAR NINGUNA INVERSI&Oacute;N</strong></span></h2>\r\n<p style=\"text-align: center;\"><span style=\"color: #ffffff; font-size: 20px;\"><strong>Incrementa tus ingresos a partir de una una comisi&oacute;n del 15% del valor de venta al p&uacute;blico.</strong></span></p>\r\n<p><span style=\"color: #000000; font-size: 20px;\">&nbsp;</span></p>', '', 0, 0, 806, 12, 8, 3, 0, 2, 807),
(809, '', '', '', '', '', '', '<h5 style=\"text-align: center;\"><strong><span style=\"font-size: 22px; color: #ffffff;\">CAPACITACI&Oacute;N AL&nbsp;DISTRIBUIDOR</span></strong></h5>\r\n<p style=\"text-align: center;\"><span style=\"font-size: 22px; color: #ffffff;\">Tenemos<strong> cursos para ventas, atenci&oacute;n al cliente y&nbsp;herramientas digitales</strong> para atraer nuevos clientes.</span></p>', '', 0, 0, 585, 12, 8, 3, 0, 2, 597),
(810, '', '', '', '', '', '', '<h5 style=\"text-align: center;\"><span style=\"color: #ffffff;\"><strong><span style=\"font-size: 22px;\">BENEFICIOS PARA EL M&Eacute;DICO</span></strong></span></h5>\r\n<p style=\"text-align: center;\"><span style=\"font-size: 22px; color: #ffffff;\">Educaci&oacute;n m&eacute;dica&nbsp; continuada y f&aacute;rmaco vigilancia.</span></p>', '', 0, 0, 585, 12, 8, 3, 0, 2, 809),
(811, '', '', '', '', '#ffffff', '', '<h3 style=\"text-align: center;\"><span style=\"color: #000000;\"><span style=\"font-size: 28px;\"><strong>GENERALIDADES DE LA&nbsp;DISTRIBUCI&Oacute;N&nbsp;</strong></span>&nbsp;</span></h3>\r\n<p style=\"text-align: center;\"><span style=\"font-size: 18px;\">Los medicamentos se entregan en consignaci&oacute;n a las farmacias y se factura cuando se haga efectiva la venta. </span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: 18px;\">El&nbsp;distribuidor deber&aacute; encargarse de visitar, vincular a los m&eacute;dicos y farmacias de su zona, y mantenerlos informados de nuevos productos, promociones y precios.</span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: 18px;\"> El&nbsp;distribuidor deber&aacute; encargarse de hacer seguimiento a la cartera y nuevos pedidos.</span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: 18px;\">Los&nbsp;distribuidor y farmacias no necesitan hacer inversi&oacute;n inicial, ni ninguna clase de inversi&oacute;n.</span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: 18px;\">En todas las ciudades donde ya existe distribuci&oacute;n local y red m&eacute;dica, deber&aacute;n respetarse contratos existentes. </span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: 18px;\">&nbsp;</span></p>', '', 0, 0, 0, 0, 8, 2, 0, 2, 808),
(812, '', '', '', '', '', '', '<h2 style=\"text-align: center;\"><span style=\"color: #ffffff; font-size: 26px;\"><strong>+1 mill&oacute;n de</strong></span></h2>\r\n<p style=\"text-align: center;\"><span style=\"color: #ffffff; font-size: 22px;\">productos vendidos el &uacute;ltimo a&ntilde;o</span></p>', '', 0, 0, 584, 3, 8, 3, 0, 2, 812),
(813, '', '', '', '', '', '', '<h2 style=\"text-align: center;\"><span style=\"color: #ffffff; font-size: 26px;\"><strong>+16 a&ntilde;os</strong></span></h2>\r\n<p style=\"text-align: center;\"><span style=\"color: #ffffff; font-size: 22px;\">al servicio de nuestros clientes</span></p>', '', 0, 0, 584, 3, 8, 3, 0, 2, 813),
(814, '', '', '', '', '', '', '<h2 style=\"text-align: center;\"><span style=\"color: #ffffff; font-size: 26px;\"><strong>+280 farmacias</strong></span></h2>\r\n<p style=\"text-align: center;\"><span style=\"color: #ffffff; font-size: 22px;\">con&nbsp;Apotecarium a nivel nacional</span></p>', '', 0, 0, 584, 3, 8, 3, 0, 2, 814),
(815, '', '', '', '', '', '', '<h2 style=\"text-align: center;\"><span style=\"color: #ffffff; font-size: 26px;\"><strong>+900 m&eacute;dicos</strong></span></h2>\r\n<p style=\"text-align: center;\"><span style=\"color: #ffffff; font-size: 22px;\">formulando nuestros productos</span></p>', '', 0, 0, 584, 3, 8, 3, 0, 2, 815),
(816, '', 'windows_azure.png', NULL, '', '', '', '', '', 0, 0, 798, 6, 12, 3, 0, 1, 816),
(822, '', '', NULL, '', '', '', '<p style=\"text-align: left;\"><span style=\"color: #ffffff;\"><strong><span style=\"font-size: 60px;\">&iquest; TIENES DUDAS?</span></strong></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: 40px; color: #ffcc00;\"><strong>Estamos aqu&iacute; para resolverlas</strong></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: 26px; color: #008000;\"><strong>Comun&iacute;cate con nosotros, llena el formulario y nos estaremos</strong></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: 26px; color: #008000;\"><strong> contactando contigo </strong><strong>lo m&aacute;s pronto posible</strong></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: 26px; color: #008000;\"><strong>Gracias por tu inter&eacute;s&nbsp;</strong></span></p>', '', 0, 0, 821, 12, 10, 3, 4, 1, 822),
(823, '', '1ah1in-0.jpg', NULL, '', '', '', '<h2 style=\"text-align: center;\"><strong><span style=\"color: #ffffff; font-size: 40px;\">APRENDE A USAR TU MENTE Y PONLA A FUNCIONAR PARA TU BENEFICIO</span></strong></h2>', '', 0, 0, 0, 0, 3, 1, 0, 2, 823),
(824, '', 'armorum_banner3.jpg', NULL, '', '', '', '<h2 style=\"text-align: center;\">&nbsp;</h2>\r\n<h2 style=\"text-align: center;\">&nbsp;</h2>\r\n<h2 style=\"text-align: center;\"><span style=\"font-size: 55px; color: #ffffff;\"><strong>SOLUCIONES PARA CADA NECESIDAD</strong></span></h2>\r\n<h2 style=\"text-align: center;\"><span style=\"font-size: 30px;\"><strong><span style=\"color: #ffffff; font-size: 28px;\"><span style=\"font-size: 38px; color: #00ccff;\">Banca de inversi&oacute;n, Servicios Bolsa Mercantil, Outsourcing Financiero</span>&nbsp; </span>&nbsp; &nbsp;&nbsp;</strong></span></h2>', '', 0, 0, 0, 0, 1, 1, 0, 1, 824),
