(840, '', '', NULL, '', '', '', '<p><span style=\"font-size: 40px; color: #008000;\"><strong>Descargue nuestra aplicaci&oacute;n</strong></span></p>\r\n<p><span style=\"font-size: 26px;\">Pague sus compras seguro, f&aacute;cil y r&aacute;pido.</span></p>\r\n<p><span style=\"font-size: 26px;\">Su billetera, en su tel&eacute;fono m&oacute;vil.</span></p>\r\n<p><span style=\"font-size: 26px;\">&iexcl;La mejor forma de llevar su dinero!</span></p>', '', 0, 0, 827, 9, 10, 3, 0, 1, 840),
