(934, '', '', NULL, 'libro_de_fondo.jpg', '#9b162b', '', '<p style=\"text-align: center;\">&nbsp;</p>\r\n<p style=\"text-align: center;\"><span style=\"color: #ffffff;\"><strong><span style=\"font-size: 40px;\"><strong><span style=\"font-size: 55px;\">7</span> </strong></span></strong><span style=\"font-size: 40px;\"><span style=\"font-size: 36px;\">pa&iacute;ses&nbsp; &nbsp; -&nbsp;&nbsp;</span></span><strong><span style=\"font-size: 40px;\"><strong><span style=\"font-size: 55px;\">8</span> </strong></span></strong><span style=\"font-size: 40px;\"><span style=\"font-size: 36px;\">casas editoriales -&nbsp; &nbsp;&nbsp;</span></span><strong><span style=\"font-size: 40px;\"><strong><span style=\"font-size: 55px;\">25</span> </strong></span></strong><span style=\"font-size: 40px;\"><span style=\"font-size: 36px;\">a&ntilde;os de experiencia</span></span></span></p>', '', 0, 0, 0, 0, 12, 2, 0, 2, 929),
