(1536, '', '', NULL, '', '', '', '<h2 style=\"text-align: right;\">&nbsp;</h2>\r\n<h2 style=\"text-align: right;\">&nbsp;<strong><span style=\"color: #333333;\"><span style=\"font-size: 26px;\">Tenemos m&aacute;s de 10 a&ntilde;os de experiencia en el mundo de la tecnolog&iacute;a, siempre orientando</span></span></strong></h2>\r\n<h2 style=\"text-align: right;\"><strong><span style=\"color: #333333;\"><span style=\"font-size: 26px;\">todos nuestros esfuerzos al mejorar el estilo</span></span></strong></h2>\r\n<h2 style=\"text-align: right;\"><strong><span style=\"color: #333333;\"><span style=\"font-size: 26px;\">de vida de nuestros clientes.</span></span></strong></h2>\r\n<h2 style=\"text-align: right;\">&nbsp;</h2>\r\n<h2 style=\"text-align: right;\"><strong><span style=\"color: #333333;\"><span style=\"font-size: 26px;\">Creemos que la tecnolog&iacute;a es la mejor</span></span></strong></h2>\r\n<h2 style=\"text-align: right;\"><strong><span style=\"color: #333333;\"><span style=\"font-size: 26px;\">forma de acercanos al futuro, y poder entender mejor el mundo.</span></span></strong></h2>', '', 0, 0, 1535, 6, 36, 3, 0, 1, 1536),
