(1556, '', '', NULL, '', '', '', '<h2 style=\"text-align: center;\">&nbsp;</h2>\r\n<h2 style=\"text-align: center;\"><span style=\"font-size: 38px;\"><strong>TODOS NUESTROS PRODUCTOS TIENEN 1 A&Ntilde;O DE GARANT&Iacute;A</strong></span></h2>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>', '', 0, 0, 1498, 12, 36, 3, 2, 1, 1556),
(1557, '', '', NULL, 'blanco.png', '', '', '<p style=\"text-align: center;\"><span style=\"font-size: 38px; color: #333333;\"><strong>&Uacute;ltimos 3 d&iacute;as para comprar el libro en preventa&nbsp;</strong></span></p>', '', 0, 0, 0, 0, 17, 2, 0, 2, 1557),
