(1883, '', '', '', '', '', '<p><strong><span style=\"color: #000000; font-size: 18px; font-weight: 400;\">La consulta m&eacute;dica especializada est&aacute; hecha pensando en Usted y en sus necesidades, donde generamos un contacto personal con el paciente, para poder encontrar un diagn&oacute;stico apropiado y preciso para su beneficio, claramente especializado en la salud cardiovascular.</span><br /></strong></p>', '', '', 136, 0, 402, 3, 7, 5, 0, 1, 1883),
(1888, '', 'starry-night.png', '', '', '', '', '<div id=\"comp-jnf1rv1j\" class=\"txtNew\" data-packed=\"true\">\r\n<h2 class=\"font_2\" style=\"text-align: right;\"><span style=\"font-size: 32px;\"><strong><span class=\"color_31\" style=\"color: #ffff99;\">DESCUBRE TU ESENCIA!</span></strong></span></h2>\r\n<p>&nbsp;&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n</div>\r\n<div id=\"comp-jnfblvr2\" class=\"txtNew\" data-packed=\"true\">\r\n<p class=\"font_2\" style=\"text-align: right;\"><span class=\"color_31\" style=\"color: #ffff99; font-size: 24px;\">Lib&eacute;rate del Sufrimiento, </span></p>\r\n<p class=\"font_2\" style=\"text-align: right;\"><span class=\"color_31\" style=\"color: #ffff99; font-size: 24px;\">recupera tu libertad, </span></p>\r\n<p class=\"font_2\" style=\"text-align: right;\"><span class=\"color_31\" style=\"color: #ffff99; font-size: 24px;\">tu confianza y desata el potencial </span></p>\r\n<p class=\"font_2\" style=\"text-align: right;\"><span class=\"color_31\" style=\"color: #ffff99; font-size: 24px;\">de tu FELICIDAD&nbsp;</span></p>\r\n<p class=\"font_2\" style=\"text-align: right;\"><span style=\"font-size: 24px;\">&nbsp;</span></p>\r\n<p class=\"font_2\" style=\"text-align: right;\"><strong><span class=\"color_31\" style=\"color: #ffff99; font-size: 24px;\">TE ENSE&Ntilde;O COMO HACERLO!</span></strong></p>\r\n</div>', '', 0, 0, 0, 0, 50, 1, 0, 1, 1888),
