(2721, '', 'gaugamela_banner_3_opc2.jpg', '', '', '', '', '<h2 style=\"text-align: left;\"><strong><span style=\"font-family: Poppins, sans-serif; font-size: 60px; color: #ffffff;\">Gaugamela</span></strong></h2>\r\n<h2 style=\"text-align: left;\"><span style=\"font-family: Rubik, sans-serif; font-size: 30px; color: #ff6600;\">Vida para tu piel</span></h2>', '', 0, 0, 0, 0, 71, 1, 0, 1, 2721),
