(13, 'Coworking', '<h3>&nbsp;</h3>\r\n<p>&nbsp;</p>\r\n<h2 style=\"text-align: center;\">&nbsp;</h2>\r\n<h2 style=\"text-align: center;\"><span style=\"font-size: 50px;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\"><span style=\"color: #ffffff;\">TOGROOW/Coworking</span></span></strong></span></h2>\r\n<h2 style=\"text-align: center;\"><span style=\"color: #ffffff; font-size: 36px;\">&Uacute;nete a la Red Social</span><br /><span style=\"color: #ffffff; font-size: 36px;\">de Negocios y Emprendimiento</span></h2>\r\n<p style=\"text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 24px; color: #ffffff;\">&nbsp;Crea una cuenta gratuita</span></p>\r\n<p>&nbsp;</p>', 'Crea tu cuenta personal y agrega tus negocios', '', 1, '', 'rgba(89,87,87,0.4)', 'landing_1-01_27.jpg', 9, '#030202', '#ffffff', '#fa0505', NULL, 56, '', 0),
(14, 'Empresa', '<h2 style=\"text-align: center;\">&nbsp;</h2>\r\n<h2 style=\"text-align: center;\">&nbsp;</h2>\r\n<h2 style=\"text-align: center;\"><span style=\"font-size: 50px;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\"><span style=\"color: #ffffff;\">TOGROOW/Empresa</span></span></strong></span></h2>\r\n<h2 style=\"text-align: center;\"><span style=\"color: #ffffff; font-size: 36px;\">&Uacute;nete a la Red Social</span><br /><span style=\"color: #ffffff; font-size: 36px;\">de Negocios y Emprendimiento</span></h2>\r\n<p style=\"text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 24px; color: #ffffff;\">&nbsp;Crea una cuenta gratuita</span></p>', 'Crea tu cuenta personal y agrega tus negocios', '', 1, '', 'rgba(89,87,87,0.4)', 'landing_1-01_28.jpg', 9, '#030202', '#ffffff', '#fa0505', NULL, 38, '', 0),
(15, 'Banca de Inversi&oacute;n', '<h2 style=\"text-align: center;\">&nbsp;</h2>\r\n<h2 style=\"text-align: center;\">&nbsp;</h2>\r\n<h2 style=\"text-align: center;\"><span style=\"font-size: 50px;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\"><span style=\"color: #ffffff;\">TOGROOW/</span></span></strong></span></h2>\r\n<h2 style=\"text-align: center;\"><span style=\"font-size: 50px;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\"><span style=\"color: #ffffff;\">Banca de Inversi&oacute;n</span></span></strong></span></h2>\r\n<h2 style=\"text-align: center;\"><span style=\"color: #ffffff; font-size: 36px;\">&Uacute;nete a la Red Social</span><br /><span style=\"color: #ffffff; font-size: 36px;\">de Negocios y Emprendimiento</span></h2>\r\n<p style=\"text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 24px; color: #ffffff;\">&nbsp;Crea una cuenta gratuita</span></p>', 'Crea tu cuenta personal y agrega tus negocios', '', 1, '#ffffff', 'rgba(89,87,87,0.4)', 'landing_1-01_210.jpg', 9, '', '#ffffff', '#fa0505', NULL, 51, '', 0),
(16, 'Crea tu cuenta personal y agrega tus negocios', '<h3><span data-sheets-value=\"{\" data-sheets-userformat=\"{\">TOGROOW/<strong>ONG</strong></span></h3>\r\n<p><span data-sheets-value=\"{\" data-sheets-userformat=\"{\">DA A CONOCER TU PROP&Oacute;SITO, ACTIVIDADES Y PROGRAMAS </span></p>\r\n<p><span data-sheets-value=\"{\" data-sheets-userformat=\"{\">CONECTA CON ALIADOS ESTRAT&Eacute;GICOS.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span data-sheets-value=\"{\" data-sheets-userformat=\"{\"><span data-sheets-value=\"{\" data-sheets-userformat=\"{\">Una ONG requiere de una red que le permita </span></span></p>\r\n<p><span data-sheets-value=\"{\" data-sheets-userformat=\"{\"><span data-sheets-value=\"{\" data-sheets-userformat=\"{\">dar&nbsp;</span></span><span data-sheets-value=\"{\" data-sheets-userformat=\"{\"><span data-sheets-value=\"{\" data-sheets-userformat=\"{\">informaci&oacute;n sobre sus actividades.</span></span></p>\r\n<p>&nbsp;</p>\r\n<h3><span data-sheets-value=\"{\" data-sheets-userformat=\"{\"><span data-sheets-value=\"{\" data-sheets-userformat=\"{\">REG&Iacute;STRATE</span></span></h3>', 'Con&eacute;ctate correctamente para hacer crecer tu negocio', '', 1, '#050505', 'rgba(255,255,255,0)', '', 18, '#050505', '#ffffff', '#fa0505', NULL, 0, '', 0),
(17, 'Consultor', '<h2 style=\"text-align: center;\">&nbsp;</h2>\r\n<h2 style=\"text-align: center;\">&nbsp;</h2>\r\n<h2 style=\"text-align: center;\"><span style=\"font-size: 50px;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\"><span style=\"color: #ffffff;\">TOGROOW/Consultor</span></span></strong></span></h2>\r\n<h2 style=\"text-align: center;\"><span style=\"color: #ffffff; font-size: 36px;\">&Uacute;nete a la Red Social</span><br /><span style=\"color: #ffffff; font-size: 36px;\">de Negocios y Emprendimiento</span></h2>\r\n<p style=\"text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 24px; color: #ffffff;\">&nbsp;Crea una cuenta gratuita</span></p>', 'Crea tu cuenta personal y agrega tus negocios', '', 1, '', 'rgba(89,87,87,0.4)', 'landing_1-01_26.jpg', 9, 'rgba(3,2,2,0)', '#ffffff', '#fa0505', NULL, 63, '', 0),
(18, 'Asociaci&oacute;n', '<h2 style=\"text-align: center;\">&nbsp;</h2>\r\n<h2 style=\"text-align: center;\">&nbsp;</h2>\r\n<h2 style=\"text-align: center;\"><span style=\"font-size: 50px;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\"><span style=\"color: #ffffff;\">TOGROOW/Asociaci&oacute;n</span></span></strong></span></h2>\r\n<h2 style=\"text-align: center;\"><span style=\"color: #ffffff; font-size: 36px;\">&Uacute;nete a la Red Social</span><br /><span style=\"color: #ffffff; font-size: 36px;\">de Negocios y Emprendimiento</span></h2>\r\n<p style=\"text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 24px; color: #ffffff;\">&nbsp;Crea una cuenta gratuita</span></p>', 'Crea tu cuenta personal y agrega tus negocios', '', 1, '', 'rgba(89,87,87,0.4)', 'landing_1-01_29.jpg', 9, 'rgba(3,2,2,0)', '#ffffff', '#fa0505', NULL, 42, '', 0),
(19, 'Apotecarium franquicias', '<h3 style=\"text-align: left;\"><strong>La oportunidad de tener </strong></h3>\r\n<h3 style=\"text-align: left;\"><strong>tu </strong><strong>propia FRANQUICIA</strong></h3>\r\n<p style=\"text-align: left;\">&nbsp;</p>\r\n<p style=\"text-align: left;\"><strong>Desarrolla una red comercial </strong></p>\r\n<p style=\"text-align: left;\"><strong>con&nbsp;</strong><strong>una&nbsp;</strong><strong>completa l&iacute;nea&nbsp;</strong><strong>de productos </strong></p>\r\n<p style=\"text-align: left;\"><strong>para la salud.&nbsp;</strong></p>\r\n<h3 style=\"text-align: center;\">&nbsp;</h3>', '', 'logoapote.png', 2, '#000000', 'rgba(15,14,14,0.02)', 'landing-6.png', 1, '#31a8dc', '#01096d', '#000000', NULL, 0, '', 0),
(20, 'Freelance', '<h2 style=\"text-align: center;\"><span style=\"font-size: 50px;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\"><span style=\"color: #ffffff;\">TOGROOW/Freelance</span></span></strong></span></h2>\r\n<h2 style=\"text-align: center;\"><span style=\"color: #ffffff; font-size: 36px;\">&Uacute;nete a la Red Social</span><br /><span style=\"color: #ffffff; font-size: 36px;\">de Negocios y Emprendimiento</span></h2>\r\n<p style=\"text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 24px; color: #ffffff;\">&nbsp;Crea una cuenta gratuita</span></p>', 'Crea tu cuenta personal y agrega tus negocios', '', 1, '#ffffff', 'rgba(89,87,87,0.4)', 'landing_1-01_22.jpg', 9, '#000000', '#ffffff', '#ff2e00', NULL, 64, '', 0),
(23, 'M&aacute;s por ti', '<h3>TU SALUD</h3>\r\n<h3>NUESTRA MISI&Oacute;N</h3>\r\n<p>&nbsp;</p>\r\n<p>Conoce nuestro programa <em>M&aacute;s por ti</em></p>\r\n<p>En ABBOTT&nbsp;nos mueve nuestro compromiso</p>\r\n<p>con tu salud.</p>\r\n<p>&nbsp;</p>\r\n<h3>&nbsp;</h3>\r\n<p>&nbsp;</p>\r\n<h3>REG&Iacute;STRATE</h3>', 'M&aacute;s por ti, un programa integral que complementa tu tratamiento.', '', 1, '#000000', 'rgba(15,14,14,0.02)', 'togroow_landing_mas_por_ti.jpg', 6, 'rgba(3,2,2,0)', '#00000', '', NULL, 0, '', 0),
(24, 'SENA', '<h3>Educaci&oacute;n para el trabajo</h3>\r\n<h3>y el desarrollo humano.</h3>\r\n<div>&nbsp;</div>\r\n<div>El conocimiento y emprendimiento</div>\r\n<div>debe ser igual para todos</div>\r\n<div>los Colombianos</div>\r\n<div>&nbsp;</div>\r\n<div>&nbsp;</div>\r\n<div>&nbsp;</div>\r\n<h3>REG&Iacute;STRATE</h3>\r\n<div>&nbsp;</div>\r\n<div>&nbsp;</div>', '1,3 millones de estudiantes, 530 Carreras presenciales, 117 centros de formaci&oacute;n.', '', 1, '#ffffff', 'rgba(255,255,255,0)', 'togroow_landing_sena.jpg', 6, '#F27727', '#ffffff', '', NULL, 0, '', 0),
(25, 'CEMEX', '<h3>Contruyendo un mejor futuro</h3>\r\n<p>&nbsp;</p>\r\n<p>Trabajamos para ofrecerle</p>\r\n<p>a cada uno de nuestros clientes</p>\r\n<p>las mejores soluciones</p>\r\n<p>&nbsp;</p>\r\n<h3>REG&Iacute;STRATE</h3>', 'Juntos construimos para alcanzar tus metas', '', 1, '#ffffff', 'rgba(0,0,0,0)', 'togroow_landing_cemex.jpg', 6, '#ffffff', '#ffffff', '', NULL, 0, '', 0),
(26, 'EMIS', '<h3>La fuente de datos empresariales</h3>\r\n<h3>de primer nivel</h3>\r\n<p>&nbsp;</p>\r\n<h3>Proporcionando acceso</h3>\r\n<h3>a la mejor informaci&oacute;n sobre</h3>\r\n<h3>m&aacute;s de 125 mercados emergentes&nbsp;</h3>\r\n<p>&nbsp;</p>\r\n<h3>REG&Iacute;STRATE</h3>', 'Conoce m&aacute;s sobre nuestras soluciones de negocios', '', 1, '#ffffff', 'rgba(255,255,255,0)', 'togroow_landing_emis.jpg', 6, '#014052', '#ffffff', '', NULL, 0, '', 0),
(27, 'ASECH', '<h3>Promovemos y defendemos</h3>\r\n<h3>el emprendimiento</h3>\r\n<p>&nbsp;</p>\r\n<p>En ASECH trabajamos cada</p>\r\n<p>d&iacute;a para hacer de Chile un mejor lugar</p>\r\n<p>para emprender.</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<h3>REG&Iacute;STRATE</h3>', 'La asociaci&oacute;n de emprendedores m&aacute;s grande de Chile', '', 1, '#36383a', 'rgba(255,255,255,0)', 'togroow_landing_asech.jpg', 6, '#FFD54F', '#36383a', '', NULL, 0, '', 0),
(28, 'VENTURES', '<h3>Situaciones y emprendedores</h3>\r\n<p>&nbsp;</p>\r\n<p>Canal de fortalecimiento para emprendedores</p>\r\n<p>y propuestas de negocios que generen valor</p>\r\n<p>y un impacto econ&oacute;mico, social y ambiental en Colombia</p>\r\n<p>&nbsp;</p>\r\n<h3>REG&Iacute;STRATE</h3>\r\n<p>&nbsp;</p>', 'Explota tu potencial', '', 1, '#10151b', 'rgba(255,255,255,0)', 'togroow_l_ventures.jpg', 6, 'rgba(148,162,176,0)', '#10151b', '', NULL, 0, '', 0),
(29, 'MET COMMUNITY', '<h3><strong>Apoyamos el emprendimiento femenino</strong></h3>\r\n<h3>&nbsp;</h3>\r\n<p>Impulsamos y apoyamos el emprendimiento femenino,</p>\r\n<p>sostenible, responsable e innovador</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<h3><strong>REG&Iacute;STRATE</strong></h3>', 'Potenciamos el uso de las tecnolog&iacute;as como eje de desarrollo emprendedor y avance social', '', 1, '#ffffff', 'rgba(15,14,14,0.02)', 'togroow_l_met.jpg', 0, 'rgba(148,162,176,0)', '#ffffff', '#b30f08', NULL, 0, '', 0),
(30, 'CRUZ VERDE', '<h3>Droguer&iacute;a para todos<br /><br /></h3>\r\n<h3>Grupo de empresas especialistas en</h3>\r\n<h3>la entrega de&nbsp;productos y servicios</h3>\r\n<h3>de salud y bienestar</h3>\r\n<p><br /><br /></p>\r\n<p>&nbsp;</p>\r\n<h3><strong>Integridad,&nbsp;</strong><strong>Excelencia e&nbsp;</strong><strong>Innovaci&oacute;n</strong></h3>\r\n<p>&nbsp;</p>\r\n<h3>REG&Iacute;STRATE</h3>', 'Contamos con m&aacute;s de 200 droguer&iacute;as a nivel nacional', '', 1, '#ffffff', 'rgba(255,255,255,0)', 'togroow_landing_cruz_verde.jpg', 0, '#008131', '#ffffff', '', NULL, 0, '', 0),
(31, 'ARMORUM', '<h3>&nbsp;Somos parte del equipo</h3>\r\n<h3>&nbsp;</h3>\r\n<p>Trabajamos por nuestros clientes</p>\r\n<p>para conseguir las mejores&nbsp;</p>\r\n<p>condiciones del mercado</p>\r\n<p>&nbsp;</p>\r\n<h3>&nbsp;</h3>\r\n<h3>REG&Iacute;STRATE</h3>\r\n<p>&nbsp;</p>', 'Somos especialistas en la estructuraci&oacute;n y gesti&oacute;n de consecuci&oacute;n de recursos', '', 1, '#092d42', 'rgba(255,255,255,0)', 'togroow_landing_armorum.jpg', 6, '#ffffff', '#092d42', '', NULL, 0, '', 0),
(32, 'AVIVA S.A.S', '<p class=\"font_4\">&nbsp;</p>\r\n<p class=\"font_4\">Prestamos servicios con los m&aacute;s</p>\r\n<p class=\"font_4\">altos est&aacute;ndares de calidad de prevenci&oacute;n</p>\r\n<p class=\"font_4\">y tratamiento de diferentes adicciones&nbsp;</p>\r\n<p class=\"font_4\">&nbsp;</p>\r\n<p class=\"font_4\">Brindamos una mejor calidad de vida&nbsp;</p>\r\n<p class=\"font_4\">a nuestros usuarios&nbsp;su circulo familiar y social.&nbsp;</p>\r\n<p class=\"font_4\">&nbsp;</p>\r\n<p class=\"font_4\">&nbsp;</p>\r\n<p class=\"font_4\">REG&Iacute;STRATE</p>', 'Centro especializado en prevenci&oacute;n y  tratamiento de las&nbsp;adicciones', '', 1, '#ffffff', 'rgba(255,255,255,0)', 'togroow_landing_aviva.jpg', 0, '#FFFFFF', '#ffffff', '', NULL, 0, '', 0),
(33, 'C&iacute;rculo de viajes', '<p>&nbsp;</p>\r\n<p>Desde&nbsp;1970&nbsp;hemos acompa&ntilde;ado a las familias colombianas</p>\r\n<p>a vivir experiencias inolvidables con</p>\r\n<p>Planes de Ahorro para Viajes.</p>\r\n<p>&nbsp;</p>\r\n<p><br />&iexcl;Conoce m&aacute;s acerca de nosotros!</p>\r\n<h3><br />Reg&iacute;strate</h3>', 'Comprometido en la generaci&oacute;n de una cultura de ahorro para viajar', '', 1, '#ffffff', 'rgba(255,255,255,0)', 'togroow_landing_circulo_de_viajes_universal.jpg', 6, '#e6f7ff', '#ffffff', '', NULL, 0, '', 0),
(34, 'KR&Eacute;DITO', '<p class=\"font_2\">&nbsp;</p>\r\n<p class=\"font_2\">&nbsp;</p>\r\n<p class=\"font_2\"><span class=\"color_15\">Ponemos a su disposici&oacute;n</span></p>\r\n<p class=\"font_2\"><span class=\"color_15\"> tecnolog&iacute;a, informaci&oacute;n y conocimiento, </span></p>\r\n<p class=\"font_2\"><span class=\"color_15\">para que usted acceda, de manera efectiva&nbsp;</span></p>\r\n<p class=\"font_2\"><span class=\"color_15\">a recursos financieros.</span></p>\r\n<p class=\"font_2\">&nbsp;</p>\r\n<p class=\"font_2\">&nbsp;</p>\r\n<h3 class=\"font_2\"><strong><span class=\"color_15\">REG&Iacute;STRATE</span></strong></h3>', 'Dinero para su negocio Negocios para su dinero', '', 1, '#494a4c', 'rgba(255,255,255,0)', 'togroow_landing_kredito.jpg', 6, '#FFFFFF', '#494a4c', '#ffffff', NULL, 0, '', 0),
(35, 'C&Aacute;MARA CHILENA DE LA CONSTRUCCI&Oacute;N', '<p>Promovemos el desarrollo y fomentamos</p>\r\n<p>la actividad de la construcci&oacute;n.</p>\r\n<p>&nbsp;</p>\r\n<p>Buscamos apoyar el bienestar de los chilenos,</p>\r\n<p>especialmente el de los trabajadores</p>\r\n<p>de la construcci&oacute;n y sus familias</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<h3>REG&Iacute;STRATE</h3>', 'Contribuyendo al bienestar de los chilenos', '', 1, '#ffffff', '#378DDA', 'togroow_camara_de_construccion_chi.jpg', 6, '#FFFFFF', '#ffffff', '', NULL, 0, '', 0),
(36, 'PHILLIP MORRIS', '<p>Somos la empresa tabacalera m&aacute;s grande de Colombia<br />y el &uacute;nico productor de cigarrillos a nivel nacional<br /><br /></p>\r\n<p>Compramos m&aacute;s del 51% de la producci&oacute;n</p>\r\n<p>de tabaco de Colombia</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<h3><strong>REG&Iacute;STRATE</strong></h3>', 'Coltabaco la afiliada de Philip Morris International&nbsp; en Colombia', '', 1, '#ffffff', '#049cda', 'togroow_landing_coltabaco.jpg', 0, '#ffffff', '#ffffff', '#102c37', NULL, 0, '', 0),
(37, 'LID EDITORIAL', '<p>Somos el Grupo editorial l&iacute;der en</p>\r\n<p>libros&nbsp;de empresa y divulgaci&oacute;n</p>\r\n<p>&nbsp;</p>\r\n<p>Contamos con m&aacute;s de 23 a&ntilde;os</p>\r\n<p>de trayectoria</p>\r\n<p>&nbsp;</p>\r\n<h3>REG&Iacute;STRATE</h3>', 'Especializados en el mundo editorial y la comunicaci&oacute;n empresarial', '', 1, '#ffffff', '#9d1b33', 'togroow_landing_lid.jpg', 0, '#ffffff', '#ffffff', '', NULL, 0, '', 0),
(38, 'GLOCAL', '<h3>Consultora especializada en</h3>\r\n<h3>proyectos e ideas de negocios</h3>\r\n<p>&nbsp;Estructuramos adecuadamente los recursos administrativos,</p>\r\n<p>financieros, contables y de comunicaci&oacute;n de su negocio</p>\r\n<p>&nbsp;</p>\r\n<h3>REG&Iacute;STRATE</h3>', '', 'glocal.png', 1, '#ffffff', '#08233f', 'togroow_landing_glocal.jpg', 18, '#ffffff', '#08233f', '', NULL, 0, '', 0),
(39, 'TOGROW/Salud', '<h2 style=\"text-align: center;\">&nbsp;&nbsp;</h2>\r\n<h2 style=\"text-align: right;\"><span style=\"font-size: 40px;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\"><span style=\"color: #ffffff;\">TOGROOW</span><span style=\"color: #003366;\">/salud</span></span></strong></span></h2>\r\n<p style=\"text-align: right;\"><span style=\"font-size: 24px; color: #ffffff;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\">&nbsp;A&ntilde;ade tu negocio a la red </span></strong></span></p>\r\n<p style=\"text-align: right;\"><span style=\"font-size: 24px; color: #ffffff;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\">y obt&eacute;n los beneficios</span></strong></span></p>\r\n<p style=\"text-align: right;\"><span style=\"font-size: 24px; color: #ffffff;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\">que TOGROOW cre&oacute; para </span></strong></span></p>\r\n<p style=\"text-align: right;\"><span style=\"font-size: 24px; color: #ffffff;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\">el sector de la salud. &nbsp;</span></strong></span></p>', 'Crea tu cuenta personal y agrega tus negocios', '', 1, '#ffffff', 'rgba(89,87,87,0.4)', 'landing_final_salud_2.jpg', 1, '#000000', '#fa0505', '#fa0505', NULL, 0, '', 0),
(40, 'Club', '<h2 style=\"text-align: center;\">&nbsp;</h2>\r\n<h2 style=\"text-align: center;\">&nbsp;</h2>\r\n<h2 style=\"text-align: center;\"><span style=\"font-size: 50px;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\"><span style=\"color: #ffffff;\">TOGROOW/Club</span></span></strong></span></h2>\r\n<h2 style=\"text-align: center;\"><span style=\"color: #ffffff; font-size: 36px;\">&Uacute;nete a la Red Social</span><br /><span style=\"color: #ffffff; font-size: 36px;\">de Negocios y Emprendimiento</span></h2>\r\n<p style=\"text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 24px; color: #ffffff;\">&nbsp;Crea una cuenta gratuita</span></p>', 'Crea tu cuenta personal y agrega tus negocios', '', 1, '#ffffff', 'rgba(89,87,87,0.4)', 'landing_1-01_211.jpg', 9, '#000000', '', '', NULL, 67, '', 0),
(41, 'Aceleradora', '<h2 style=\"text-align: center;\">&nbsp;</h2>\r\n<h2 style=\"text-align: center;\">&nbsp;</h2>\r\n<h2 style=\"text-align: center;\"><span style=\"font-size: 50px;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\"><span style=\"color: #ffffff;\">TOGROOW/ Aceleradora</span></span></strong></span></h2>\r\n<h2 style=\"text-align: center;\"><span style=\"color: #ffffff; font-size: 36px;\">&Uacute;nete a la Red Social</span><br /><span style=\"color: #ffffff; font-size: 36px;\">de Negocios y Emprendimiento</span></h2>\r\n<p style=\"text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 24px; color: #ffffff;\">&nbsp;Crea una cuenta gratuita</span></p>', '', '', 1, '#ffffff', 'rgba(89,87,87,0.4)', 'landing_1-01_212.jpg', 9, '', '', '', NULL, 54, '', 0),
(42, 'Incubadora', '<h2 style=\"text-align: right;\">&nbsp;</h2>\r\n<h2 style=\"text-align: right;\">&nbsp;</h2>\r\n<h2 style=\"text-align: center;\">&nbsp;<span style=\"font-size: 50px;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\"><span style=\"color: #ffffff;\">TOGROOW/Incubadora</span></span></strong></span></h2>\r\n<h2 style=\"text-align: center;\"><span style=\"color: #ffffff; font-size: 36px;\">&Uacute;nete a la Red Social</span><br /><span style=\"color: #ffffff; font-size: 36px;\">de Negocios y Emprendimiento</span></h2>\r\n<p style=\"text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 24px; color: #ffffff;\">&nbsp;Crea una cuenta gratuita</span></p>', 'Crea tu cuenta personal y agrega tus negocios', '', 1, '#ffffff', 'rgba(89,87,87,0.4)', 'landing_1-01_213.jpg', 9, '#000000', '', '', NULL, 53, '', 0),
(43, 'Instituci&oacute;n Educativa', '<h2 style=\"text-align: right;\">&nbsp;</h2>\r\n<h2 style=\"text-align: right;\">&nbsp;</h2>\r\n<h2 style=\"text-align: center;\"><span style=\"font-size: 50px;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\"><span style=\"color: #ffffff;\">TOGROOW/</span></span></strong></span></h2>\r\n<h2 style=\"text-align: center;\"><span style=\"font-size: 50px;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\"><span style=\"color: #ffffff;\">Instituci&oacute;n Educativa</span></span></strong></span></h2>\r\n<h2 style=\"text-align: center;\"><span style=\"color: #ffffff; font-size: 36px;\">&Uacute;nete a la Red Social</span><br /><span style=\"color: #ffffff; font-size: 36px;\">de Negocios y Emprendimiento</span></h2>\r\n<p style=\"text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 24px; color: #ffffff;\">&nbsp;Crea una cuenta gratuita</span></p>', 'Crea tu cuenta personal y agrega tus negocios', '', 1, '#ffffff', 'rgba(89,87,87,0.4)', 'landing_1-01_214.jpg', 9, '#000000', '#000000', '', NULL, 46, '', 0),
(44, 'Franquicia', '<h2 style=\"text-align: center;\">&nbsp;</h2>\r\n<h2 style=\"text-align: center;\">&nbsp;</h2>\r\n<h2 style=\"text-align: center;\"><span style=\"font-size: 50px;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\"><span style=\"color: #ffffff;\">TOGROOW/Franquicia</span></span></strong></span></h2>\r\n<h2 style=\"text-align: center;\"><span style=\"color: #ffffff; font-size: 36px;\">&Uacute;nete a la Red Social</span><br /><span style=\"color: #ffffff; font-size: 36px;\">de Negocios y Emprendimiento</span></h2>\r\n<p style=\"text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 24px; color: #ffffff;\">&nbsp;Crea una cuenta gratuita</span></p>', 'Crea tu cuenta personal y agrega tus negocios', '', 1, '#ffffff', 'rgba(89,87,87,0.4)', 'landing_1-01_215.jpg', 9, '#000000', '#000000', '', NULL, 39, '', 0),
(45, 'Company  Builder', '<h2 style=\"text-align: center;\">&nbsp;</h2>\r\n<h2 style=\"text-align: center;\"><span style=\"font-size: 50px;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\"><span style=\"color: #ffffff;\">TOGROOW/</span></span></strong></span></h2>\r\n<h2 style=\"text-align: center;\"><span style=\"font-size: 50px;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\"><span style=\"color: #ffffff;\">Company Builder</span></span></strong></span></h2>\r\n<h2 style=\"text-align: center;\"><span style=\"color: #ffffff; font-size: 36px;\">&Uacute;nete a la Red Social</span><br /><span style=\"color: #ffffff; font-size: 36px;\">de Negocios y Emprendimiento</span></h2>\r\n<p style=\"text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 24px; color: #ffffff;\">&nbsp;Crea una cuenta gratuita</span></p>', 'Crea tu cuenta personal y agrega tus negocios', '', 1, '#ffffff', 'rgba(89,87,87,0.4)', 'landing_1-01_216.jpg', 9, '#000000', '#000000', '', NULL, 55, '', 0),
