(67, 'TOGROOW/MujeresEmprendedoras', '<h2 style=\"text-align: right;\"><span style=\"font-size: 12px;\">&nbsp;</span></h2>\r\n<h2 style=\"text-align: right;\"><span style=\"font-size: 50px; color: #333333;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\">TOGROOW/</span></strong></span></h2>\r\n<h2 style=\"text-align: right;\"><span style=\"font-size: 50px; color: #4a4948;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\">Mujeres </span></strong></span></h2>\r\n<h2 style=\"text-align: right;\"><span style=\"font-size: 50px; color: #4a4948;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\">Emprendedoras</span></strong></span></h2>\r\n<h2 style=\"text-align: right;\"><span style=\"color: #808080;\">&nbsp;</span></h2>\r\n<h2 style=\"text-align: right;\"><span style=\"color: #808080;\">&nbsp;<span style=\"font-size: 28px; color: #333333;\"><strong>&Uacute;nete a la comunidad&nbsp;que</strong></span></span></h2>\r\n<h2 style=\"text-align: right;\"><span style=\"font-size: 28px; color: #333333;\"><strong>promueve el rol de la mujer </strong></span></h2>\r\n<h2 style=\"text-align: right;\"><span style=\"font-size: 28px; color: #333333;\"><strong>en los negocios</strong></span></h2>\r\n<p style=\"text-align: right;\"><span style=\"font-size: 12px;\">&nbsp;</span></p>\r\n<p style=\"text-align: right;\"><span style=\"color: #4a4948;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 20px;\">Una red social creada&nbsp;</span><span style=\"font-family: arial, helvetica, sans-serif; font-size: 20px;\">para</span></span></p>\r\n<p style=\"text-align: right;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 20px; color: #4a4948;\">generar contactos.</span></p>', 'Crea tu cuenta personal y agrega tus negocios', '', 1, '#ffffff', 'rgba(89,89,89,0.37)', 'landing_final_mujeres_emprendedoras.jpg', 1, '#000000', '#fa0505', '#fa0505', NULL, 0, '', 0),
(68, 'TOGROOW/Social', '<h2 style=\"text-align: right;\"><span style=\"font-size: 12px;\">&nbsp;</span></h2>\r\n<h2 style=\"text-align: right;\"><span style=\"font-size: 50px;\"><strong><span style=\"font-family: helvetica, arial, sans-serif; color: #ffffff;\">TOGROOW/</span></strong></span></h2>\r\n<h2 style=\"text-align: right;\"><span style=\"font-size: 50px; color: #383026;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\">Social</span></strong></span></h2>\r\n<h2 style=\"text-align: right;\"><span style=\"font-size: 22px; color: #ffffff;\">&Uacute;nete a la<span style=\"font-size: 26px;\"><strong> comunidad</strong></span></span></h2>\r\n<h2 style=\"text-align: right;\"><span style=\"font-size: 26px;\"><strong><span style=\"color: #ffffff;\">que&nbsp;promueve</span></strong></span></h2>\r\n<h2 style=\"text-align: right;\"><span style=\"font-size: 26px;\"><strong><span style=\"color: #ffffff;\">proyectos sociales</span></strong></span></h2>\r\n<h2 style=\"text-align: right;\"><span style=\"font-size: 26px;\"><strong><span style=\"color: #ffffff;\">con impacto positivo</span></strong></span></h2>\r\n<h3 style=\"text-align: right;\"><span style=\"color: #362a2a;\">&nbsp;</span></h3>\r\n<p style=\"text-align: right;\"><span style=\"color: #362a2a;\"><span style=\"font-size: 36px;\">&nbsp;</span>&nbsp;</span></p>\r\n<p style=\"text-align: right;\"><span style=\"color: #ffffff;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 20px;\">Una red social creada&nbsp;</span><span style=\"font-family: arial, helvetica, sans-serif; font-size: 20px;\">para</span></span></p>\r\n<p style=\"text-align: right;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 20px; color: #ffffff;\">generar contactos.</span></p>', 'Crea tu cuenta personal y agrega tus negocios', '', 1, '#ffffff', 'rgba(89,89,89,0.37)', 'landing_final_social.jpg', 1, '#000000', '#fa0505', '#fa0505', NULL, 0, '', 0),
(69, 'TOGROOW/Econom&iacute;aNaranja', '<h2 style=\"text-align: right;\"><span style=\"font-size: 50px;\"><strong><span style=\"font-family: helvetica, arial, sans-serif; color: #ffffff;\">TOGROOW/</span></strong></span></h2>\r\n<h2 style=\"text-align: right;\"><span style=\"font-size: 50px; color: #363331;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\">Econom&iacute;a Naranja</span></strong></span></h2>\r\n<h3 style=\"text-align: right;\"><span style=\"color: #ffffff; font-size: 32px;\">&Uacute;nete a la comunidad</span></h3>\r\n<h3 style=\"text-align: right;\"><span style=\"color: #ffffff;\"><span style=\"font-size: 32px;\">promotora de&nbsp;</span><span style=\"font-size: 32px;\">las ideas&nbsp;que</span></span></h3>\r\n<h3 style=\"text-align: right;\"><span style=\"color: #ffffff; font-size: 32px;\">enriquecen la cultura</span></h3>\r\n<p style=\"text-align: right;\"><span style=\"color: #ffffff;\"><span style=\"font-size: 36px;\">&nbsp;</span>&nbsp;</span></p>\r\n<p style=\"text-align: right;\"><span style=\"color: #ffffff;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 20px;\">Una red social creada </span><span style=\"font-family: arial, helvetica, sans-serif; font-size: 20px;\">para </span></span></p>\r\n<p style=\"text-align: right;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 20px; color: #ffffff;\">generar contactos.</span></p>', 'Crea tu cuenta personal y agrega tus negocios', '', 1, '#ffffff', 'rgba(89,89,89,0.37)', 'landing_final_economia_naranja.jpg', 1, '#000000', '#fa0505', '#fa0505', NULL, 0, '', 0),
(70, 'TOGROOW/Pensionados', '<h2 style=\"text-align: right;\"><span style=\"font-size: 50px; color: #381704;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\">TOGROOW/</span></strong></span></h2>\r\n<h2 style=\"text-align: right;\"><span style=\"font-size: 50px; color: #a67433;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\">Pensionados</span></strong></span></h2>\r\n<h3 style=\"text-align: right;\"><span style=\"color: #381704;\"><span style=\"font-size: 32px;\">&Uacute;nete a la comunidad</span></span></h3>\r\n<h3 style=\"text-align: right;\"><span style=\"color: #381704;\"><span style=\"font-size: 32px;\">que&nbsp;</span><span style=\"font-size: 32px;\">promueve </span><span style=\"font-size: 32px;\">una </span></span></h3>\r\n<h3 style=\"text-align: right;\"><span style=\"color: #381704;\"><span style=\"font-size: 32px;\">vejez productiva</span></span></h3>\r\n<p style=\"text-align: right;\"><span style=\"color: #381704;\"><span style=\"font-size: 36px;\">&nbsp;</span>&nbsp;</span></p>\r\n<p style=\"text-align: right;\"><span style=\"color: #381704;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 20px;\">Una red social creada&nbsp;</span><span style=\"font-family: arial, helvetica, sans-serif; font-size: 20px;\">para</span></span></p>\r\n<p style=\"text-align: right;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 20px; color: #381704;\">generar contactos.</span></p>', 'Crea tu cuenta personal y agrega tus negocios', '', 1, '#ffffff', 'rgba(89,89,89,0.37)', 'landing_final_pensionados.jpg', 1, '#000000', '#fa0505', '#fa0505', NULL, 0, '', 0),
(71, 'TOGROOW/Benefits', '<h2 style=\"text-align: right;\"><span style=\"font-size: 50px; color: #ffffff;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\">TOGROOW/</span></strong></span></h2>\r\n<h2 style=\"text-align: right;\"><span style=\"font-size: 50px; color: #ffffff;\"><strong><span style=\"font-family: helvetica, arial, sans-serif;\">Benefits</span></strong></span></h2>\r\n<h3 style=\"text-align: right;\"><span style=\"color: #ffffff;\"><span style=\"font-size: 32px;\">Reg&iacute;strate para ser </span></span></h3>\r\n<h3 style=\"text-align: right;\"><span style=\"color: #ffffff;\"><span style=\"font-size: 32px;\">el primero en conocer </span></span></h3>\r\n<h3 style=\"text-align: right;\"><span style=\"color: #ffffff;\"><span style=\"font-size: 32px;\">las mejores promociones </span></span></h3>\r\n<h3 style=\"text-align: right;\"><span style=\"color: #ffffff;\"><span style=\"font-size: 32px;\">de todo lo que necesitas</span></span></h3>\r\n<p style=\"text-align: right;\"><span style=\"color: #ffffff;\"><span style=\"font-size: 36px;\">&nbsp;</span>&nbsp;</span></p>\r\n<p style=\"text-align: right;\"><span style=\"color: #ffffff;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 20px;\">Una red social creada&nbsp;</span><span style=\"font-family: arial, helvetica, sans-serif; font-size: 20px;\">para</span></span></p>\r\n<p style=\"text-align: right;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 20px; color: #ffffff;\">generar contactos de negocio.</span></p>\r\n<p style=\"text-align: right;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 20px; color: #ffffff;\"><img src=\"http://www.togroow.com/upload/yekologopng.png\" alt=\"yekologopng\" /></span></p>', 'Crea tu cuenta personal para usar los beneficios', '', 1, '#ffffff', 'rgba(89,89,89,0.37)', 'togroow_red_benefits.jpg', 1, '#000000', '#fa0505', '#fa0505', NULL, 0, '', 0),
(72, 'DOT', '<h2 style=\"text-align: right;\">&nbsp;</h2>\r\n<h2 style=\"text-align: right;\">&nbsp;</h2>\r\n<h2 style=\"text-align: right;\">&nbsp;</h2>\r\n<h2 style=\"text-align: right;\"><span style=\"font-size: 22px;\"><strong><span style=\"color: #ffffff; font-size: 30px;\">El centro de </span></strong></span></h2>\r\n<h2 style=\"text-align: right;\"><span style=\"font-size: 22px;\"><strong><span style=\"color: #ffffff; font-size: 30px;\">innovaci&oacute;n&nbsp;</span></strong></span><strong><span style=\"color: #ffffff; font-size: 30px;\">y coworking para </span></strong></h2>\r\n<h2 style=\"text-align: right;\"><strong><span style=\"color: #ffffff; font-size: 30px;\">las organizaciones </span></strong><strong><span style=\"color: #ffffff; font-size: 30px;\">de impacto social</span></strong></h2>\r\n<p><span style=\"color: #ffffff;\"><img src=\"http://www.togroow.com/upload/logodot.png\" alt=\"logodot\" /></span></p>', 'Completa estos datos y accede a los beneficios', '', 1, '#ffffff', 'rgba(89,89,89,0.37)', 'dot_1anding.jpg', 1, '#000000', '#fa0505', '#fa0505', NULL, 0, '', 0),
(73, 'POLI', '<h3>RED POLIEMPRENDE</h3>\r\n<h3>SOMOS DIFERENTES</h3>\r\n<h4>Somos Poli&nbsp;</h4>\r\n<div>&nbsp;</div>\r\n<h3>Unete a la red de conocimiento,</h3>\r\n<h3>emprendimiento</h3>\r\n<h3>y negocios del Poli.</h3>', 'Completa estos datos y accede a los beneficios', '', 1, '#ffffff', 'rgba(89,89,89,0.37)', 'poli1.jpg', 1, '#000000', '#001c8b', '#fa0505', NULL, 0, '', 0),
(75, 'Sportodos', '<h2 style=\"text-align: right;\"><strong><span style=\"font-family: tahoma, arial, helvetica, sans-serif; font-size: 50px;\"><em><span style=\"color: #008000;\"><span style=\"color: #ff6600;\">SporT</span><span style=\"color: #99cc00;\">odos</span></span></em></span></strong></h2>\r\n<h2 style=\"text-align: right;\"><span style=\"color: #ffffff; font-family: \'arial black\', sans-serif;\"><span style=\"font-size: 24px;\">&Uacute;nete a la comunidad&nbsp;</span><span style=\"font-size: 24px;\">que&nbsp;</span></span></h2>\r\n<h2 style=\"text-align: right;\"><span style=\"color: #ffffff; font-family: \'arial black\', sans-serif;\"><span style=\"font-size: 24px;\">promueve&nbsp;</span><span style=\"font-size: 24px;\">el mundo&nbsp;</span></span></h2>\r\n<h2 style=\"text-align: right;\"><span style=\"color: #ffffff; font-family: \'arial black\', sans-serif;\"><span style=\"font-size: 24px;\">del deporte en&nbsp;</span><span style=\"font-size: 24px;\">Latinoam&eacute;rica</span></span></h2>\r\n<h2 style=\"text-align: right;\"><span style=\"color: #000000;\"><span style=\"font-family: \'arial black\', sans-serif;\"><span style=\"font-size: 36px;\">&nbsp;</span><em><span style=\"font-size: 20px;\">&nbsp;<span style=\"font-family: arial, helvetica, sans-serif; color: #ffffff;\"><strong>Entra en el juego</strong></span></span></em></span></span></h2>\r\n<h4 style=\"text-align: right;\">&nbsp;</h4>\r\n<h4 style=\"text-align: right;\"><span style=\"color: #000000; font-size: 14px; font-family: \'arial black\', sans-serif;\">Powered by</span></h4>\r\n<p><span style=\"color: #000000;\"><img src=\"http://www.togroow.com/upload/sportodos02.png\" alt=\"sportodos02\" /></span></p>', '&Uacute;nete al juego', '', 1, '#ffffff', 'rgba(36,33,33,0.4)', 'landing-final-sportodos.jpg', 9, '', '#ffffff', '', NULL, 117, '', 0);
