INSERT INTO `muro` (`muro_id`, `muro_redsocial`, `muro_tipo`, `muro_ancho`, `muro_fondo_color`, `muro_fondo_imagen`, `muro_tipo_fondo_imagen`, `muro_titulo`, `muro_texto`, `orden`) VALUES
(6, 3, 2, 1, '#f2f2f2', 'landing_nuevo.jpg', 11, 'Encabezado', '<h2 style=\"text-align: left;\" align=\"center\">&nbsp;</h2>\r\n<h2 style=\"text-align: left;\" align=\"center\"><span style=\"font-family: helvetica, arial, sans-serif;\"><span style=\"color: #1f3f80; font-size: 40px;\"><strong>FRANQUICIAS </strong></span><span style=\"color: #1f3f80; font-size: 40px;\"><strong>APOTECARIUM</strong></span></span></h2>\r\n<p><span style=\"font-size: 32px; font-family: helvetica, arial, sans-serif;\"><span style=\"color: #4a4c68; font-size: 30px;\">M&Eacute;DICOS <span style=\"font-size: 32px;\">|</span> VISITADORES <span style=\"font-size: 32px;\">|</span> DROGUER&Iacute;AS</span></span></p>\r\n<p><span style=\"font-family: helvetica, arial, sans-serif;\">&nbsp;</span></p>\r\n<h2 style=\"text-align: left;\"><span style=\"font-family: helvetica, arial, sans-serif;\"><span style=\"font-size: 30px;\"><strong><span style=\"color: #1f3f80;\">LA <span style=\"color: #1f3f80;\">OPORTUNIDAD</span> DE&nbsp;</span></strong></span><span style=\"font-size: 30px;\"><strong><span style=\"color: #1f3f80;\">TENER </span></strong></span></span></h2>\r\n<h2 style=\"text-align: left;\"><span style=\"font-family: helvetica, arial, sans-serif;\"><span style=\"font-size: 30px;\"><strong><span style=\"color: #1f3f80;\">T</span><span style=\"color: #1f3f80;\">U PROPIA FRANQUICIA</span></strong></span></span></h2>\r\n<h4><span style=\"font-family: helvetica, arial, sans-serif;\">&nbsp;<span style=\"font-size: 26px; color: #125496;\">Desarrolla una red comercial con una </span></span></h4>\r\n<h4><span style=\"font-size: 26px; color: #125496; font-family: helvetica, arial, sans-serif;\">&nbsp;completa l&iacute;nea de productos para la salud</span></h4>\r\n<p><span style=\"font-family: helvetica, arial, sans-serif;\">&nbsp;</span></p>', 5),
(8, 3, 1, 1, '#38a6cb', 'landing_nuevo__cuerpo_2.jpg', 1, 'T&eacute;rminos y Condiciones', '<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: 38px; color: #ffffff;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">T&eacute;rminos y Condiciones</span></strong></span></p>\r\n<p><span style=\"font-size: 18px; color: #ffffff;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">M&eacute;dicos</span></strong></span></p>\r\n<ul>\r\n<li>\r\n<p><span style=\"font-size: 18px; color: #ffffff;\">Afiliaci&oacute;n a la cooperativa Omecop. (por la cual reciben beneficios en educaci&oacute;n m&eacute;dica continuada y f&aacute;rmaco vigilancia).</span></p>\r\n</li>\r\n<li>\r\n<p><span style=\"font-size: 18px; color: #ffffff;\">Conferencias m&eacute;dicas frecuentes</span></p>\r\n</li>\r\n</ul>\r\n<p><span style=\"color: #ffffff;\"><span style=\"font-size: 18px;\">&nbsp;</span><span style=\"font-size: 18px;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">Farmacias</span></strong></span></span></p>\r\n<ul>\r\n<li>\r\n<p><span style=\"color: #ffffff; font-size: 18px;\">Comisi&oacute;n del 10%, del valor de de venta al p&uacute;blico.</span></p>\r\n</li>\r\n</ul>\r\n<p><span style=\"color: #ffffff;\"><span style=\"font-size: 18px;\">&nbsp;</span><span style=\"font-size: 18px;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">Distribuidores o visitadores m&eacute;dicos</span></strong></span></span></p>\r\n<ul>\r\n<li>\r\n<p><span style=\"color: #ffffff; font-size: 18px;\">Comisi&oacute;n del 15%, del valor de venta al p&uacute;blico:</span></p>\r\n</li>\r\n<li>\r\n<p><span style=\"color: #ffffff; font-size: 18px;\">Los medicamentos se entregan en consignaci&oacute;n a las farmacias y se factura, seg&uacute;n a medida que se va vendiendo.</span></p>\r\n</li>\r\n<li>\r\n<p><span style=\"color: #ffffff; font-size: 18px;\">El distribuidor o franquiciado deber&aacute; encargarse de visitar, vincular a los m&eacute;dicos y farmacias de su zona, y mantenerlos informados de nuevos productos, promociones, precios.etc.</span></p>\r\n</li>\r\n<li>\r\n<p><span style=\"color: #ffffff; font-size: 18px;\">El distribuidor tambi&eacute;n deber&aacute; encargarse de hacer seguimiento a la cartera y nuevos pedidos.</span></p>\r\n</li>\r\n<li>\r\n<p><span style=\"color: #ffffff; font-size: 18px;\">Las farmacias firman pagar&eacute;.</span></p>\r\n</li>\r\n</ul>\r\n<p><span style=\"color: #ffffff;\"><span style=\"font-size: 18px;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">&nbsp;</span></strong></span><span style=\"font-size: 18px;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">NOTA ESPECIAL:</span></strong></span></span></p>\r\n<ul>\r\n<li>\r\n<p><span style=\"color: #ffffff; font-size: 18px;\">En todas las ciudades donde ya existe distribuci&oacute;n local y red medica, deber&aacute;n respetarse contratos existentes.</span></p>\r\n</li>\r\n<li>\r\n<p><span style=\"color: #ffffff; font-size: 18px;\">&nbsp;Los distribuidores o franquiciados y farmacias, no necesitan hacer inversi&oacute;n inicial, ni ninguna clase de inversi&oacute;n.</span></p>\r\n</li>\r\n</ul>\r\n<p><span style=\"font-size: 18px; color: #ffffff;\">&nbsp;</span></p>\r\n<p><span style=\"font-size: 18px; color: #ffffff;\">&nbsp;</span></p>\r\n<p><span style=\"font-size: 18px; color: #ffffff;\">&nbsp;</span></p>', 9),
(9, 3, 2, 1, '#d0e2f8', 'landing_cue.jpg', 0, 'Cuerpo', '<h2>&nbsp;</h2>\r\n<h2><strong><span style=\"font-family: helvetica, arial, sans-serif; font-size: 40px; color: #244279;\">Incrementa tus ingresos a partir de una una comisi&oacute;n del 15% del valor de venta al p&uacute;blico.</span></strong></h2>\r\n<p>&nbsp;</p>\r\n<h2><span style=\"font-size: 38px; font-family: helvetica, arial, sans-serif;\"><span style=\"color: #244279;\">Pasos a seguir</span></span></h2>\r\n<p>&nbsp;</p>\r\n<ul>\r\n<li>\r\n<h4><span style=\"color: #244279; font-family: helvetica, arial, sans-serif;\"><strong>Paso 1:</strong> <span style=\"color: #49a7d1;\">Completar formulario.</span></span></h4>\r\n</li>\r\n</ul>\r\n<h4><span style=\"font-family: helvetica, arial, sans-serif;\">&nbsp;</span></h4>\r\n<ul>\r\n<li>\r\n<h4><span style=\"color: #244279; font-family: helvetica, arial, sans-serif;\"><strong>Paso 2:</strong> <span style=\"color: #49a7d1;\">Realizar registro telef&oacute;nico.</span></span></h4>\r\n</li>\r\n</ul>\r\n<h4><span style=\"font-family: helvetica, arial, sans-serif;\">&nbsp;</span></h4>\r\n<ul>\r\n<li>\r\n<h4><span style=\"color: #244279; font-family: helvetica, arial, sans-serif;\"><strong>Paso 3:</strong> <span style=\"color: #49a7d1;\">Entrevista individual.</span></span></h4>\r\n</li>\r\n</ul>\r\n<h4><span style=\"font-family: helvetica, arial, sans-serif;\">&nbsp;</span></h4>\r\n<ul>\r\n<li>\r\n<h4><span style=\"color: #244279; font-family: helvetica, arial, sans-serif;\"><strong>Paso 4:</strong> <span style=\"color: #49a7d1;\">Confirmaci&oacute;n de entrevista.</span></span></h4>\r\n</li>\r\n</ul>\r\n<h4><span style=\"font-family: helvetica, arial, sans-serif;\">&nbsp;</span></h4>\r\n<ul>\r\n<li>\r\n<h4><span style=\"color: #244279; font-family: helvetica, arial, sans-serif;\"><strong>Paso 5:</strong> <span style=\"color: #49a7d1;\">Per&iacute;odo de prueba.</span></span></h4>\r\n</li>\r\n</ul>\r\n<p><span style=\"font-family: helvetica, arial, sans-serif;\">&nbsp;</span></p>\r\n<p><span style=\"font-family: helvetica, arial, sans-serif;\">&nbsp;</span></p>', 8),
(10, 13, 2, 1, '#123b57', '', 1, 'Encabezado', '<h2><span style=\"font-size: 40px; color: #ffffff;\">Armorum</span></h2>\r\n<h3><span style=\"color: #ffffff;\">Somos parte del equipo</span></h3>\r\n<p><span style=\"color: #ffffff;\">&nbsp;</span></p>\r\n<h3><span style=\"color: #ffffff;\">Trabajamos por nuestros clientes</span></h3>\r\n<p><span style=\"color: #ffffff;\">para conseguir las mejores&nbsp;</span></p>\r\n<p><span style=\"color: #ffffff;\">condiciones del mercado</span></p>\r\n<p><span style=\"color: #ffffff;\">&nbsp;</span></p>\r\n<h3>&nbsp;</h3>', 10),
(11, 13, 2, 1, '#ededed', '', 0, '&iquest;Qui&eacute;nes somos?', '<h2>&iquest;Qui&eacute;nes somos?</h2>\r\n<p>Somos una Banca de Inversi&oacute;n especializada en consecuci&oacute;n de deuda con entidades financieras nacionales y extranjeras.</p>\r\n<p>Nuestro principal objetivo es trabajar por nuestros clientes y as&iacute; conseguir las mejores condiciones del mercado.</p>\r\n<p><strong><span style=\"font-size: 14px;\">Hemos logrado conseguir financiaci&oacute;n en el &uacute;ltimo a&ntilde;os por $80.000 millones en compa&ntilde;&iacute;as de sectores como:</span></strong></p>\r\n<ul>\r\n<li>Tecnolog&iacute;a</li>\r\n<li>Agroindustria</li>\r\n<li>Infraestructura</li>\r\n<li>Construcci&oacute;n</li>\r\n<li>Manufactura</li>\r\n<li>Textil e hidrocarburos</li>\r\n<li>Valoraciones en compa&ntilde;&iacute;as de sectores av&iacute;cola, servicios petroleros, metal&uacute;rgico, gas, el&eacute;ctrico, salud, manufacturero y financiero</li>\r\n</ul>', 11),
(12, 19, 1, 1, '#082340', '', 0, 'Encabezado', '<h2><span style=\"font-size: 38px; color: #ffffff;\">GLOCAL&nbsp;</span></h2>\r\n<p>&nbsp;</p>\r\n<h3><span style=\"color: #ffffff;\">Somos una consultora especializada en proyectos e ideas de negocios</span></h3>\r\n<p><span style=\"color: #ffffff;\">Te ayudamos y asesoramos en el desarrollo de tu idea, proyecto o negocios</span></p>', 12),
(13, 19, 2, 1, 'rgba(255,255,255,0.75)', '', 0, '&iquest;Qui&eacute;nes somos?', '<h2><span style=\"font-size: 38px;\">&iquest;Qu&eacute; hacemos?</span></h2>\r\n<p><span style=\"font-size: 20px;\">&bull; Estructuraci&oacute;n Financiera </span></p>\r\n<p><span style=\"font-size: 20px;\">&bull; Banca de inversi&oacute;n</span></p>\r\n<p><span style=\"font-size: 20px;\"> &bull; Administraci&oacute;n Personas naturales o jur&iacute;dicas&nbsp;</span></p>\r\n<p><span style=\"font-size: 20px;\">&bull; Revisi&oacute;n fiscal </span></p>\r\n<p><span style=\"font-size: 20px;\">&bull; Marketing &amp; Branding </span></p>\r\n<p><span style=\"font-size: 20px;\">&bull; Interventor&iacute;a </span></p>\r\n<p><span style=\"font-size: 20px;\">&bull; Estrategia</span></p>', 13),
(14, 19, 2, 1, '#082340', '', 0, 'Ultima secci&oacute;n', '<p><span style=\"color: #ffffff; font-size: 30px;\">Junto a nosotros, puedes optimizar de manera din&aacute;mica:</span></p>\r\n<p><span style=\"font-size: 22px; color: #ffffff;\">Cualquier toma de decisiones</span><br /><span style=\"color: #ffffff; font-size: 22px;\">Consecuci&oacute;n de fondos, implementaci&oacute;n</span><br /><span style=\"color: #ffffff; font-size: 22px;\">Desarrollo y posicionamiento</span><br /><span style=\"color: #ffffff; font-size: 22px;\">Puedes conocer integralmente lo que quieres hacer y las implicaciones de manera din&aacute;mica.</span></p>', 14),
(15, 3, 2, 1, '#ffffff', 'boton_6.jpg', 0, 'Call to action', '<p style=\"text-align: center;\"><span style=\"font-family: helvetica, arial, sans-serif; color: #ffffff;\"><strong><span style=\"font-size: 40px;\">&iexcl;APLICA YA!</span></strong></span></p>', 15);
