(56, 'Estructuraci&oacute;n jur&iacute;dica', '5_estructuracion_juridica-min.jpg', '<p style=\"text-align: center;\"><span style=\"font-size: 18px; color: #000080;\">&nbsp;An&aacute;lisis y estructuraci&oacute;n figura jur&iacute;dica implementada o a implementar, acta de constituci&oacute;n, acuerdo accionario, modelos de asociaci&oacute;n y negocios.</span></p>', 6, '2018-07-18 15:33:22', 210, 2, 141, NULL),
(57, 'Integraci&oacute;n estrat&eacute;gica de &aacute;reas para maximizaci&oacute;n de valor', '6_integracion_estrategica.jpg', '<p style=\"text-align: center;\"><span style=\"font-size: 18px; color: #000080;\">An&aacute;lisis y estructuraci&oacute;n de la integraci&oacute;n estrat&eacute;gica de cada una de las &aacute;reas para la optimizaci&oacute;n integral y maximizaci&oacute;n de valor.</span></p>', 6, '2018-07-18 15:42:42', 210, 2, 141, NULL),
