(59, 'Cehaler', 'cehaler.png', '<p><span style=\"font-size: 22px;\"><strong>Indicaciones</strong>&nbsp;</span></p>\r\n<ul>\r\n<li><span style=\"font-size: 16px;\">Rinitis al&eacute;rgica</span></li>\r\n<li><span style=\"font-size: 16px;\">Urticaria Idiop&aacute;tica</span></li>\r\n<li><span style=\"font-size: 16px;\">Conjuntivitis Al&eacute;rgica</span></li>\r\n</ul>\r\n<p><span style=\"font-size: 22px;\"><strong>Presentaci&oacute;n:&nbsp;</strong></span></p>\r\n<p><span style=\"font-size: 16px;\">Caja x10 tabletas</span></p>\r\n<p>&nbsp;</p>', 1, '2018-07-27 09:46:20', 115, 1, 140, NULL),
(60, 'Optiser', 'optiser.png', '<p><span style=\"font-size: 22px;\">Indicaciones</span></p>\r\n<ul>\r\n<li><span style=\"font-size: 16px;\">Rinitis al&eacute;rgica o estacional</span></li>\r\n<li><span style=\"font-size: 16px;\">Urticaria idiop&aacute;tica cr&oacute;nica</span></li>\r\n</ul>\r\n<p><span style=\"font-size: 22px;\">Presentaci&oacute;n</span></p>\r\n<p><span style=\"font-size: 16px;\">Caja x14&nbsp; tabletas</span></p>\r\n<p><span style=\"font-size: 22px;\">&nbsp;</span></p>', 1, '2018-07-27 09:52:59', 115, 1, 140, NULL),
(61, 'REQUELAR', 'requelar_x_500_002.jpg', '<p><strong><span style=\"font-size: 22px;\">Indicaciones</span></strong></p>\r\n<ul>\r\n<li><span style=\"font-size: 16px;\">Infecci&oacute;n de las v&iacute;as respiratorias altas y bajas</span></li>\r\n<li><span style=\"font-size: 16px;\">Infecci&oacute;n de la piel y tejido blando</span></li>\r\n<li><span style=\"font-size: 16px;\">Manejo del Helicobacter pylori</span></li>\r\n<li><span style=\"font-size: 16px;\">Eficaz contra infecciones originadas por Chlamydia y Mycoplasma</span></li>\r\n</ul>\r\n<p><strong><span style=\"font-size: 22px;\">Presentaci&oacute;n:</span></strong></p>\r\n<p><span style=\"font-size: 16px;\">Caja x10 tabletas</span></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>', 6, '2019-01-17 11:29:06', 115, 1, 140, 0),
(62, 'PANDOMIL', 'pandomil.png', '<p><span style=\"font-size: 22px;\">Indicaciones</span></p>\r\n<ul>\r\n<li><span style=\"font-size: 16px;\">Episodios depresivos mayores</span></li>\r\n<li><span style=\"font-size: 16px;\">Trastorno obsesivo-compulsivo</span></li>\r\n<li><span style=\"font-size: 16px;\">Trastornos de angustia</span></li>\r\n<li><span style=\"font-size: 16px;\">Trastorno de ansiedad social</span></li>\r\n<li><span style=\"font-size: 16px;\">Trastorno por estr&eacute;s postraum&aacute;tico</span></li>\r\n<li><span style=\"font-size: 16px;\">Coadyuvante en el tratamiento del colon irritable, obesidad y eyaculaci&oacute;n precoz por&nbsp;ansiedad</span></li>\r\n</ul>\r\n<p><span style=\"font-size: 22px;\">Presentaci&oacute;n</span></p>\r\n<p><span style=\"font-size: 16px;\">Caja x20 tabletas</span></p>', 1, '2018-07-27 10:12:02', 115, 1, 140, NULL),
(63, 'FLONAR', 'flonar.png', '<p><span style=\"font-size: 22px;\">Indicaciones</span></p>\r\n<ul>\r\n<li><span style=\"font-size: 16px;\">Dolor agudo</span></li>\r\n<li><span style=\"font-size: 16px;\">Osteoartritis</span></li>\r\n<li><span style=\"font-size: 16px;\">Espondilitis Anquilosante</span></li>\r\n<li><span style=\"font-size: 16px;\">Dolor menstrual&nbsp;</span></li>\r\n</ul>\r\n<p><span style=\"font-size: 22px;\">Presentaci&oacute;n</span></p>\r\n<p><span style=\"font-size: 16px;\">Caja x10 c&aacute;psulas</span></p>', 1, '2018-07-27 10:17:35', 115, 1, 140, NULL),
(64, 'Timat', 'timat_003.jpg', '<h4><span style=\"font-size: 26px;\">Indicaciones</span></h4>\r\n<ul>\r\n<li><span style=\"font-size: 16px;\">Antial&eacute;rgico, antiinflamatorio corticoesteroideo de acci&oacute;n local</span></li>\r\n<li><span style=\"font-size: 16px;\">P&oacute;lipos nasales</span></li>\r\n<li><span style=\"font-size: 16px;\">Alerg&iacute;a nasal</span></li>\r\n<li><span style=\"font-size: 16px;\">Rinitis vasomotora</span></li>\r\n</ul>\r\n<h4><span style=\"font-size: 26px;\">Presentaci&oacute;n</span></h4>\r\n<p><span style=\"font-size: 16px;\">Inhalador nasal 150 dosisx100 mcg dosis, frascox 7.5ml</span></p>', 6, '2019-01-17 11:22:01', 115, 1, 140, 0),
(65, 'Amlotens/HCT', 'amlotens_amlodipino_hidroclorotiazida_apotecarium_laboratorio_farmaceutico.png', '<h2><span style=\"font-size: 22px;\">Indicaciones</span></h2>\r\n<ul>\r\n<li><span style=\"font-size: 16px;\">Antihipertensivo.</span></li>\r\n<li><span style=\"font-size: 16px;\">Antianginoso.</span></li>\r\n<li><span style=\"font-size: 16px;\">Calcio antagonista.</span></li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<h2><span style=\"font-size: 22px;\">Presentaci&oacute;n</span></h2>\r\n<p><span style=\"font-size: 16px;\">Caja x 30 tabletas recubiertas</span></p>', 1, '2019-01-17 12:09:28', 115, 1, 140, 0),
