(68, 'AVOSAL', 'avosal.png', '<h2><span style=\"font-size: 20px;\">Indicaciones</span></h2>\r\n<p><span style=\"font-size: 16px;\">Infecciones del tracto respiratorio superior e inferior</span></p>\r\n<p><span style=\"font-size: 16px;\">Exacerbaci&oacute;n aguda de bronquitis cr&oacute;nica&nbsp;</span></p>\r\n<p><span style=\"font-size: 16px;\">Neumon&iacute;a nosocomial adquirida en la comunidad&nbsp;</span></p>\r\n<p><span style=\"font-size: 16px;\">Infecciones de piel y tejidos blandos, tales como: imp&eacute;tigo, abscesos, forunculosis, celulitis y erisipela</span></p>\r\n<p><span style=\"font-size: 16px;\">Infecciones urinarias y ginecol&oacute;gicas</span></p>\r\n<p>&nbsp;</p>\r\n<h2><span style=\"font-size: 20px;\">Presentaci&oacute;n</span></h2>\r\n<p><span style=\"font-size: 20px;\">Caja x10 tabletas</span></p>', 1, '2018-07-27 15:57:10', 115, 1, 140, NULL),
(70, 'Zolpra', 'zolpra.png', '<h2><strong><span style=\"font-size: 20px;\">Indicaciones</span></strong></h2>\r\n<p><span style=\"font-size: 16px;\">Infecci&oacute;n del tracto respiratorio superior e inferior</span></p>\r\n<p><span style=\"font-size: 16px;\">Otitis medio infecciosa-&nbsp; Sinusitis</span></p>\r\n<p><span style=\"font-size: 16px;\">Faringoamigdalitis-Bronquitis</span></p>\r\n<p><span style=\"font-size: 16px;\">Neomon&iacute;a</span></p>\r\n<h2><strong><span style=\"font-size: 20px;\">Presentaci&oacute;n</span></strong></h2>\r\n<p><span style=\"font-size: 16px;\">Caja x14 c&aacute;psulas</span></p>', 1, '2018-07-27 16:21:44', 115, 1, 140, NULL),
(71, 'ISAVAN', 'isavan.png', '<h4><span style=\"font-size: 26px;\">Indicaciones</span></h4>\r\n<p><span style=\"font-size: 16px;\">Antirreum&aacute;tico- Antiartr&iacute;tico</span></p>\r\n<p><span style=\"font-size: 16px;\">Artritis reumatoidea</span></p>\r\n<p><span style=\"font-size: 16px;\">Osteoartrosis</span></p>\r\n<p><span style=\"font-size: 16px;\">Tendinitis</span></p>\r\n<p><span style=\"font-size: 16px;\">Procesos inflamatorioa agudos y cr&oacute;nicos</span></p>\r\n<h4><span style=\"font-size: 26px;\">Presentaci&oacute;n</span></h4>\r\n<p><span style=\"font-size: 16px;\">Caja x10 tabletas</span></p>\r\n<p>&nbsp;</p>', 1, '2018-07-27 16:38:55', 115, 1, 140, NULL),
(72, 'Portener', 'portener.png', '<h4><span style=\"font-size: 26px;\">Indicaciones</span></h4>\r\n<p><span style=\"font-size: 16px;\">Artritis reumatoidea</span></p>\r\n<p><span style=\"font-size: 16px;\">Procesos inflamatorios, agudos y cr&oacute;nicos</span></p>\r\n<p><span style=\"font-size: 16px;\">Dolor agudo y cr&oacute;nico</span></p>\r\n<p>&nbsp;</p>\r\n<h4><span style=\"font-size: 26px;\">Presentaci&oacute;n</span></h4>\r\n<p><span style=\"font-size: 16px;\">Caja x15 tabletas.</span></p>', 1, '2018-07-27 16:42:35', 115, 1, 140, NULL),
