(2, 'TOGROOW', '<h2 style=\"text-align: left;\"><span style=\"font-size: 32px; font-family: Lato, sans-serif;\"><strong><span style=\"color: #ffffff;\">&iexcl;BIENVENIDO!</span></strong></span></h2>\r\n<p style=\"text-align: left;\">&nbsp;</p>\r\n<h2 style=\"text-align: left;\"><span style=\"font-family: Lato, sans-serif; font-size: 26px; color: #ffffff;\">Empieza a utilizar la</span></h2>\r\n<h2 style=\"text-align: left;\"><span style=\"color: #ffffff; font-family: Lato, sans-serif; font-size: 26px;\">red para conseguir <strong>clientes.</strong></span></h2>\r\n<h2 style=\"text-align: left;\"><span style=\"font-family: Lato, sans-serif; font-size: 26px; color: #ffffff;\"><strong>Paso 1:</strong> crea tus perfiles</span></h2>\r\n<h2 style=\"text-align: left;\"><span style=\"font-family: Lato, sans-serif; font-size: 26px; color: #ffffff;\">de negocio</span></h2>\r\n<p style=\"text-align: left;\">&nbsp;</p>', '', 'togroow_red_social_de_negocios-001.jpg', '#f93e12', 1, 'https://togroow.com/sistem/negocios/#paso1', 1, 0, 2, 'CREAR PERFIL', '2019-02-01', '2019-04-30', 0, 2),
