(12, 'TOGROOW/Econom&iacute;aNaranja', '<h2 style=\"text-align: left;\"><span style=\"font-size: 32px; font-family: Lato, sans-serif; color: #333333;\"><strong>&iexcl;BIENVENIDO!</strong></span></h2>\r\n<p style=\"text-align: left;\"><span style=\"color: #333333;\">&nbsp;</span></p>\r\n<h2 style=\"text-align: left;\"><span style=\"font-family: Lato, sans-serif; font-size: 26px; color: #333333;\">Empieza a utilizar la&nbsp;</span><span style=\"color: #333333; font-family: Lato, sans-serif; font-size: 26px;\">red</span></h2>\r\n<h2 style=\"text-align: left;\"><span style=\"color: #333333; font-family: Lato, sans-serif; font-size: 26px;\">para conseguir&nbsp;<strong>clientes.</strong></span></h2>\r\n<h2 style=\"text-align: left;\"><strong><span style=\"font-family: Lato, sans-serif; font-size: 26px; color: #333333;\">El primer paso es&nbsp;crear tus</span></strong></h2>\r\n<h2 style=\"text-align: left;\"><strong><span style=\"font-family: Lato, sans-serif; font-size: 26px; color: #333333;\">perfiles&nbsp;</span><span style=\"font-family: Lato, sans-serif; font-size: 26px; color: #333333;\">de negocio.</span></strong></h2>\r\n<h2 style=\"text-align: left;\"><span style=\"font-family: Lato, sans-serif; font-size: 26px; color: #333333;\">Haz click en</span></h2>\r\n<p style=\"text-align: left;\"><span style=\"color: #333333;\">&nbsp;</span></p>', '', 'togroow_red_social_de_negocios-12.png', '', 1, '', 1, 0, 2, 'CREAR PERFIL', NULL, NULL, NULL, 12),
(13, 'TOGROOW/BusinessKnowledge', '<h2 style=\"text-align: left;\"><span style=\"font-size: 32px; font-family: Lato, sans-serif; color: #ffffff;\"><strong>&iexcl;BIENVENIDO!</strong></span></h2>\r\n<p style=\"text-align: left;\"><span style=\"color: #ffffff;\">&nbsp;</span></p>\r\n<h2 style=\"text-align: left;\"><span style=\"color: #ffffff;\"><span style=\"font-family: Lato, sans-serif; font-size: 26px;\">Empieza a utilizar la&nbsp;</span><span style=\"font-family: Lato, sans-serif; font-size: 26px;\">red</span></span></h2>\r\n<h2 style=\"text-align: left;\"><span style=\"color: #ffffff; font-family: Lato, sans-serif; font-size: 26px;\">para conseguir&nbsp;<strong>clientes.</strong></span></h2>\r\n<h2 style=\"text-align: left;\"><span style=\"color: #ffffff;\"><strong><span style=\"font-family: Lato, sans-serif; font-size: 26px;\">El primer paso es&nbsp;crear tus</span></strong></span></h2>\r\n<h2 style=\"text-align: left;\"><span style=\"color: #ffffff;\"><strong><span style=\"font-family: Lato, sans-serif; font-size: 26px;\">perfiles&nbsp;</span><span style=\"font-family: Lato, sans-serif; font-size: 26px;\">de negocio.</span></strong></span></h2>\r\n<h2 style=\"text-align: left;\"><span style=\"color: #ffffff;\"><span style=\"font-family: Lato, sans-serif; font-size: 26px;\">Haz click en</span>&nbsp;</span></h2>', '', 'togroow_red_social_de_negocios-13.png', '', 1, '', 1, 0, 2, 'CREAR PERFIL', '2019-02-01', '2019-04-30', 0, 13),
(14, 'Beneficios de la red Salud Alternativa', '<h2><span style=\"font-size: 30px; color: #ffffff;\"><strong>Utiliza la red para:</strong></span></h2>\r\n<h2><span style=\"font-size: 30px; color: #ffffff;\">Estar a la vanguardia en temas como,&nbsp;</span><br /><span style=\"font-size: 30px; color: #ffffff;\">- Estilos de vida saludable&nbsp;</span><br /><span style=\"font-size: 30px; color: #ffffff;\">- Homeopat&iacute;a</span><br /><span style=\"font-size: 30px; color: #ffffff;\">- Medicina ancestral</span></h2>\r\n<p style=\"text-align: left;\">&nbsp;</p>', '', 'togroow_red_social_de_negocios_m-14.png', '', 0, '', 1, 0, 2, '', '2019-02-01', '2019-04-30', 0, 14),
(15, 'Beneficios de la red Salud Alternativa', '<h2><span style=\"font-size: 30px; color: #ffffff;\"><strong>Aprovecha la comunidad para:</strong></span></h2>\r\n<h2><span style=\"font-size: 30px; color: #ffffff;\">Dar a conocer tus productos&nbsp;</span><br /><span style=\"font-size: 30px; color: #ffffff;\">o servicios, relacionados al</span><br /><span style=\"font-size: 30px; color: #ffffff;\">sector de salud alternativa</span></h2>', '', 'togroow_red_social_de_negocios_m-15.png', '', 0, '', 1, 0, 2, '', '2019-02-01', '2019-04-30', 0, 15),
(16, 'Gracias por ser parte de la comunidad', '<h2><strong><span style=\"color: #ffffff; font-size: 30px;\">Queremos agradecerte, tienes&nbsp;</span></strong><br /><strong><span style=\"color: #ffffff; font-size: 30px;\">descuento del 10%</span></strong></h2>\r\n<h2><span style=\"color: #ffffff; font-size: 30px;\">en todos nuestros servicios:</span><br /><span style=\"color: #ffffff; font-size: 30px;\">Creaci&oacute;n de sitios web</span><br /><span style=\"color: #ffffff; font-size: 30px;\">Campa&ntilde;as de mercadeo</span><br /><span style=\"color: #ffffff; font-size: 30px;\">y mucho m&aacute;s</span></h2>', '', 'togroow_red_social_de_negocios-16.png', '', 0, '', 2, 0, 2, '', '2019-02-01', '2019-04-30', 0, 16),
(17, 'Beneficios de la red Ecuestre', '<h2><span style=\"font-size: 28px; color: #ffffff;\"><strong>Utiliza la red para:<br /></strong>Estar a la vanguardia en temas como,&nbsp;</span><br /><span style=\"font-size: 28px; color: #ffffff;\">- Campeonatos de Polo&nbsp;</span><br /><span style=\"font-size: 28px; color: #ffffff;\">- Competencias de saltos</span><br /><span style=\"font-size: 28px; color: #ffffff;\">- Nueva tecnolog&iacute;a ecuestre</span></h2>', '', 'ecuestre1.jpg', '', 0, '', 1, 0, 2, '', '2019-02-01', '2019-04-30', 0, 17),
(18, 'Beneficios de la red Ecuestre', '<h2><span style=\"font-size: 28px; color: #ffffff;\"><strong>Aprovecha la comunidad para<br /></strong>Dar a conocer y comercializar</span><span style=\"font-size: 28px; color: #ffffff;\"> tus productos&nbsp;</span><br /><span style=\"font-size: 28px; color: #ffffff;\">o servicios, relacionados al&nbsp;</span><span style=\"font-size: 28px; color: #ffffff;\">sector</span></h2>', '', 'ecuestre2.jpg', '', 0, '', 1, 0, 2, '', '2019-02-01', '2019-04-30', 0, 18),
(19, 'TOGROOW', '<h2 style=\"text-align: left;\"><strong><span style=\"color: #ffffff; font-family: Montserrat, sans-serif; font-size: 30px;\">Personaliza tu experiencia en TOGROOW.</span>&nbsp;</strong></h2>', '', 'pop_up_personalizado.jpg', '', 1, 'https://www.togroow.com/sistem/usuario/intereses/', 1, 0, 2, 'PERSONALIZAR', '2019-02-01', '2019-05-30', 0, 19);
