INSERT INTO `registro` (`registro_id`, `registro_nombre`, `registro_imagen`, `registro_fondo`, `registro_video`, `registro_introduccion`, `registro_descripcion`, `registro_categoria`, `registro_sitio`, `registro_tags`, `registro_pais`, `registro_otropais`, `registro_ciudad`, `registro_sector`, `registro_pagina`, `registro_direccion`, `registro_fecha`, `registro_contacto_georeferenciacion`, `registro_contacto_nombre`, `registro_contacto_correo`, `registro_contacto_telefono`, `registro_contacto_cargo`, `registro_contacto_datos`, `registro_contacto_celular`, `registro_contacto_horario`, `registro_usuario`, `registro_fecha_edicion`, `registro_eliminado`, `registro_identificador`) VALUES
(258, 'DOT centro de innovaci&oacute;n y coworking', 'imageperfil2581.jpg', 'dot_portada_togroow_abril_2019.jpg', '', 'En DOT conectamos los puntos, conectamos gente, los conectamos con las oportunidades. Nuestra visión es ser el centro de encuentro de los proyectos con propósito.', '<p>Pensando en nuestros amigos genios, colegas echados pa\' lante y esa gente que se la est&aacute; jugando toda por su emprendimiento, creamos DOT. El lugar perfecto para darle a su idea ese toque profesional que necesita y con los mejores precios del mercado.</p>\r\n<p>DOT es un centro de innovaci&oacute;n y coworking, donde tenemos como visi&oacute;n ser el epicentro donde convergen los talentos que lideran la cuarta revoluci&oacute;n industrial en Colombia. Nuestra misi&oacute;n es ser el punto catalizador de sinergias entre freelancers, emprendedores, tele-trabajadores, empresas y organizaciones de la econom&iacute;a naranja que tienen como premisa transformar la educaci&oacute;n, maximizar el uso de la tecnolog&iacute;a y generar impacto social. En DOT, estamos convencidos que cuando se une la tecnolog&iacute;a, la educaci&oacute;n y el impacto social, por un mismo objetivo, se crean puntos de transformaci&oacute;n social y econ&oacute;mica que dejan huella para siempre. Ese es nuestro prop&oacute;sito.</p>\r\n<p>&nbsp;</p>\r\n<p>TODOS NUESTROS&nbsp; PLANES&nbsp;INCLUYEN</p>\r\n<ul>\r\n<li>Wifi y puntos de internet por cable.</li>\r\n<li>Vigilancia 24/7.</li>\r\n<li>Servicio de impresi&oacute;n, copias y esc&aacute;ner.</li>\r\n<li>Servicios p&uacute;blicos.</li>\r\n<li>Servicio de aseo general.</li>\r\n<li>Servicio de recepci&oacute;n.</li>\r\n<li>Cabinas telef&oacute;nicas privadas.</li>\r\n<li>Caf&eacute; y agua ilimitados.</li>\r\n<li>Se&ntilde;alizaci&oacute;n y protocolos seg&uacute;n norma.</li>\r\n<li>P&oacute;liza de seguro.</li>\r\n<li>Dog friendly.</li>\r\n<li>Bicicleteros.</li>\r\n<li>Acceso a cafeter&iacute;a.</li>\r\n<li>Pagos electr&oacute;nicos y con tarjeta de cr&eacute;dito.</li>\r\n<li>Eventos*.</li>\r\n</ul>\r\n<p><br />*Todas los meses se realizar&aacute;n eventos gratuitos. DOT se reserva el derecho de realizar eventos no gratuitos.</p>\r\n<p>**Descuento para pagos anticipados.</p>\r\n<p>***Descuento especial para organizaciones con m&aacute;s de 6 personas.</p>\r\n<p><strong>Escr&iacute;benos a&nbsp;hola@dotinnovacion.com&nbsp;para solicitudes especiales y planes empresariales a la medida.</strong></p>', 38, 0, '', 'Colombia', '', 'Bogot&aacute;', 'Servicios', '', 'Carrera 27A # 70-92', '2019-06-18 11:50:12', '4.6625245,-74.07008580000002', 'Andrea Calderon', 'andreacalderonleal@gmail.com', '310 215 4560', '', 'hola@dotinnovacion.com', '222 1648', '', 444, '2019-06-18 11:50:13', NULL, NULL),
(259, 'Desarrollo Superior', '', '', '', 'Soy SicoTerapeuta con  25 años de experiencia. Apoyo a personas estresadas o con duelos, rupturas, etc. Tengo una estrategia para Sanar las distintas formas de Nacer. Ofrezco \"Yoga de la RISA\" a Empresas, para elevar el clima laboral y  laproduccion.', '<p>* Ofrezco Consultas y Sesiones individualizadas de una Terapia que se llama VITALIZACION, para Adultos estresados que han experimentado una ruptura o un duelo. La Consulta dura 2 horas y los Consultantes refieren que sienten como \"Si se quitaran un morral, que pesaba mucho y ahora sienten el alivio\". Y se sienten Vitalizados.</p>\r\n<p>*Ofrezco Terapias de Vidas Pasadas, sin hipnosis. Es un Turismo Interior. Seguro. Es una Aventura inolvidable.</p>\r\n<p>*Ofrezco \"YOGA de LA RISA\" para Empresas en sus Celebraciones o cuando 2 departamentos estan en conflicto, esta practica ayuda a mejorar el Clima Laboral y por lo tanto la Producctividad.</p>\r\n<p>&nbsp;Se puede usar tambien para Premiar el rendimiento de un departamento Administrativo o como Pausas Activas.</p>\r\n<p>*Ademas tengo una especializacion en Renacimiento, que es muy &uacute;til para Sanar las distintas formas de Nacer. Como la Cesar&eacute;a y el Forceps, por ejemplo.</p>\r\n<p>&nbsp;</p>', 28, 0, '', 'Colombia', 'Si, cuando me invitan. Antes labore en Estados Unidos.', 'Bogota', 'Consultoria', '', 'Calle 108 N&ordm; 14 B - 49', '2019-06-12 13:47:41', '4.691585,-74.04476399999999', 'Bernardo Martin', 'bernardomartin35@gmail.com', '3103079011', '', 'bernardomar2238@gmail.com', '3103079011', '', 0, '2019-06-12 13:47:41', NULL, NULL),
