(315, 'Camiseta A MARTE mas no pude', 'amartemasnopude.jpg', '', '', '', '<ul>\r\n<li>Camiseta confeccionada localmente.</li>\r\n<li>Pintado a mano.</li>\r\n<li>Camiseta Fit Masculino, mangas amplias.</li>\r\n<li>100% Franela de algod&oacute;n.</li>\r\n</ul>', 0.00, 0, 208, 0, 0, '2019-05-24', 1, '', 0, 0, 0.00, NULL, NULL, '', '', '', '', '', '', 1, 0, 0, '', 0, '', ''),
(316, 'Abrigo Penny Lane', 'abrigoesquimal3.jpg', '', '', '', '<p>Abrigo caf&eacute;, forro interno en seda.&nbsp;</p>\r\n<p>Capota forrada, con detalle en peluche.&nbsp;</p>\r\n<p>Cremallera frontal, con detalle en peluche.</p>\r\n<p>Mangas con detalle en peluche.&nbsp;</p>\r\n<p>Bolsillos laterales.&nbsp;</p>\r\n<p>Talla S-M&nbsp;</p>', 0.00, 0, 208, 0, 0, '2019-05-24', 1, '', 0, 0, 0.00, NULL, NULL, '', '', '', '', '', '', 1, 0, 0, '', 0, '', ''),
