(392, 'Banca de Inversi&oacute;n', '115.jpg', '', '', '', '<p style=\"text-align: justify;\"><span style=\"font-size: 14px; font-family: Roboto, sans-serif;\">Campo Capital S.A.S. es un link entre los recursos de capital disponibles para inversi&oacute;n en agricultura y reforestaci&oacute;n, con los proyectos y empresas del campo que requieren de financiamiento, bien sea v&iacute;a equity o deuda, para el desarrollo y expansi&oacute;n de estas. El servicio de Banca de Inversi&oacute;n es un servicio que Campo Capital S.A.S. desarrolla para terceros y para proyectos propios en el momento de la salida de inversiones, haciendo el puente entre el Capital y el Campo.</span></p>', 0.00, 0, 189, 0, 0, '2019-06-19', 1, '', 0, 1, 0.00, NULL, NULL, '', '', '', '', '', '', 2, 0, 0, '', 0, '', ''),
(393, 'EKRANOPLAN', 'ekranoplan.jpg', '', '', '', '<p style=\"font-weight: 400;\"><u>INDICACIONES:</u></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\">Por ser rico en fibra previene la formaci&oacute;n de divert&iacute;culos.</li>\r\n<li style=\"font-weight: 400;\">Disminuye ostensiblemente los s&iacute;ntomas del llamado &ldquo;colon irritable&rdquo;</li>\r\n<li style=\"font-weight: 400;\">Previene enfermedades cardiovasculares y desordenes intestinales.</li>\r\n</ul>\r\n<p style=\"font-weight: 400;\"><u>PRESENTACION</u>:</p>\r\n<p style=\"font-weight: 400;\">Tarro x 400 gr</p>', 0.00, 0, 140, 0, 0, '2019-06-12', 1, '', 0, 1, 0.00, NULL, NULL, '', '', '', 'EKRANOPLAN,gastrointestinal,medicina', '', '', 1, 16, 0, '', 0, '', ''),
(394, 'GASTROSEF', 'gastrosef.jpg', '', '', '', '<p style=\"font-weight: 400;\"><u>INDICACIONES</u>:</p>\r\n<ul>\r\n<li style=\"font-weight: 400;\">Ulcera G&aacute;strica</li>\r\n<li style=\"font-weight: 400;\">Tratamiento sintom&aacute;tico del reflujo gastroesof&aacute;gico.</li>\r\n<li style=\"font-weight: 400;\">Tratamiento de la &uacute;lcera p&eacute;ptica y duodenal, complicaciones del tratamiento de AINES.</li>\r\n<li style=\"font-weight: 400;\">S&iacute;ndrome de Zollinger-Ellison.</li>\r\n<li style=\"font-weight: 400;\">Erradicaci&oacute;n del helicobacter pylori en &uacute;lcera p&eacute;ptica.</li>\r\n</ul>\r\n<p style=\"font-weight: 400;\"><u>PRESENTACION</u>:</p>\r\n<p style=\"font-weight: 400;\">Caja x 14 c&aacute;psulas</p>', 0.00, 0, 140, 0, 0, '2019-06-12', 1, '', 0, 1, 0.00, NULL, NULL, '', '', '', 'GASTROSEF,Gastrointestinal,medicina', '', '', 1, 16, 0, '', 0, '', ''),
(395, 'SEROTEG', 'seroteg.jpg', '', '', '', '<p style=\"font-weight: 400;\"><u>INDICACIONES</u>:</p>\r\n<ul>\r\n<li style=\"font-weight: 400;\">Estre&ntilde;imiento</li>\r\n<li style=\"font-weight: 400;\">Colon Irritable</li>\r\n<li style=\"font-weight: 400;\">Disminuye los niveles de colesterol</li>\r\n<li style=\"font-weight: 400;\">Previene el C&aacute;ncer de Colon</li>\r\n<li style=\"font-weight: 400;\">Ayuda a mantener un peso saludable</li>\r\n<li style=\"font-weight: 400;\">Controla los niveles de glucosa e insulina</li>\r\n</ul>\r\n<p style=\"font-weight: 400;\"><u>PRESENTACION:</u></p>\r\n<p style=\"font-weight: 400;\">Tarro x 200 gr</p>', 0.00, 0, 140, 0, 0, '2019-06-12', 1, '', 0, 1, 0.00, NULL, NULL, '', '', '', 'SEROTEG,medicina,Gastrointestinal', '', '', 1, 16, 0, '', 0, '', ''),
