(1177, 'Cr&eacute;ditos', '', '', 1, 34, 82, 0, NULL),
(1178, 'Representante de la obra', 'DIEGO A. AGUDELO', '', 1, 34, 62, 0, NULL),
(1179, 'T&iacute;tulo', 'ING. CIVIL', '', 1, 34, 61, 0, NULL),
