(1186, 'Constructor (nombre persona y/o empresa)', 'PROMOTORA 144 SAS', '', 1, 34, 63, 0, NULL),
(1187, 'Tel&eacute;fono', '7444828', '', 1, 34, 64, 0, NULL),
